    fn load_step_gesture_source(runtime: &mut Runtime) {
        // S2 moved the step gesture defs from ui/main.lisp into the
        // step-grid-interactions section file.
        let src = std::fs::read_to_string("ui/step-grid-interactions.lisp")
            .expect("read ui/step-grid-interactions.lisp");
        let start = src
            .find("(def selection-click?")
            .expect("step gesture source should define selection-click?");
        let end = src
            .find("(def seq-set-step-param-from-step")
            .expect("step gesture source should precede step param helpers");
        runtime
            .eval_str(&format!(
                "(module eseq.step-grid-interactions)\n{}",
                &src[start..end]
            ))
            .expect("load step gesture source");
    }

    fn load_keyboard_step_selection_source(runtime: &mut Runtime) {
        // S2 moved the keyboard step selection defs from ui/main.lisp into
        // the step-grid-interactions section file.
        let src = std::fs::read_to_string("ui/step-grid-interactions.lisp")
            .expect("read ui/step-grid-interactions.lisp");
        // The anchor is pinned into `eseq.vanilla` (module spec §10 hazard m):
        // ui/bus-grid.lisp (eseq.bus-grid) shares this gesture slot and
        // `set!`s it through the same `eseq.vanilla/` spelling.
        let start = src
            .find("(def eseq.vanilla/step-key-select-anchor")
            .expect("keyboard step selection source should define anchor");
        let end = src
            .find("(def cursor-toggle")
            .expect("keyboard step selection source should precede cursor-toggle");
        runtime
            .eval_str(&format!(
                "(module eseq.step-grid-interactions)\n{}",
                &src[start..end]
            ))
            .expect("load keyboard step selection source");
    }

    fn register_step_gesture_test_natives(
        runtime: &mut Runtime,
        steps: Arc<Mutex<Vec<bool>>>,
        selected: Arc<Mutex<Vec<bool>>>,
        toggles: Arc<Mutex<Vec<usize>>>,
        moves: Arc<Mutex<Vec<(usize, usize)>>>,
        ranges: Arc<Mutex<Vec<(usize, usize)>>>,
        picks: Arc<Mutex<Vec<usize>>>,
        clock: Arc<Mutex<f64>>,
    ) {
        runtime.register_native("eseq.seq-core-state/cool-off-follow", |_args, _ctx| Ok(Value::Nil));

        {
            let clock = clock.clone();
            runtime.register_native("now-ms", move |_args, _ctx| {
                Ok(Value::Number(*clock.lock().unwrap()))
            });
        }
        {
            let clock = clock.clone();
            runtime.register_native("test-set-now-ms", move |args, _ctx| {
                let Some(Value::Number(ms)) = args.first() else {
                    return Err("test-set-now-ms: expected milliseconds".into());
                };
                *clock.lock().unwrap() = *ms;
                Ok(Value::Nil)
            });
        }

        let selected_for_has_selection = selected.clone();
        runtime.register_native("seq-has-selection?", move |_args, _ctx| {
            Ok(Value::Bool(
                selected_for_has_selection
                    .lock()
                    .unwrap()
                    .iter()
                    .any(|selected| *selected),
            ))
        });

        let selected_for_lookup = selected.clone();
        runtime.register_native("seq-step-selected?", move |args, _ctx| {
            let Some(Value::Number(step)) = args.first() else {
                return Err("seq-step-selected?: expected step".into());
            };
            Ok(Value::Bool(
                selected_for_lookup.lock().unwrap()[*step as usize],
            ))
        });

        let selected_for_indexes = selected.clone();
        runtime.register_native("seq-selected-step-indexes-native", move |_args, _ctx| {
            Ok(Value::List(
                selected_for_indexes
                    .lock()
                    .unwrap()
                    .iter()
                    .enumerate()
                    .filter(|(_, selected)| **selected)
                    .map(|(step, _)| Rc::new(RefCell::new(Value::Number(step as f64))))
                    .collect(),
            ))
        });

        let steps_for_active = steps.clone();
        runtime.register_native("seq-track-step-active?", move |args, _ctx| {
            let Some(Value::Number(step)) = args.get(1) else {
                return Err("seq-track-step-active?: expected track and step".into());
            };
            Ok(Value::Bool(
                steps_for_active.lock().unwrap()[*step as usize],
            ))
        });

        let steps_for_toggle = steps.clone();
        let toggles_for_toggle = toggles.clone();
        runtime.register_native("seq-toggle-step", move |args, _ctx| {
            let Some(Value::Number(step)) = args.first() else {
                return Err("seq-toggle-step: expected step".into());
            };
            let step = *step as usize;
            let mut steps = steps_for_toggle.lock().unwrap();
            steps[step] = !steps[step];
            toggles_for_toggle.lock().unwrap().push(step);
            Ok(Value::Bool(steps[step]))
        });

        let moves_for_drag = moves.clone();
        runtime.register_native("seq-move-step-drag", move |args, _ctx| {
            let (Some(Value::Number(start)), Some(Value::Number(target))) =
                (args.first(), args.get(1))
            else {
                return Err("seq-move-step-drag: expected start and target".into());
            };
            moves_for_drag
                .lock()
                .unwrap()
                .push((*start as usize, *target as usize));
            Ok(Value::Bool(true))
        });

        let ranges_for_select = ranges.clone();
        let selected_for_range = selected.clone();
        runtime.register_native("seq-select-step-range", move |args, _ctx| {
            let (Some(Value::Number(start)), Some(Value::Number(end))) =
                (args.first(), args.get(1))
            else {
                return Err("seq-select-step-range: expected start and end".into());
            };
            let start = *start as usize;
            let end = *end as usize;
            ranges_for_select.lock().unwrap().push((start, end));
            let mut selected = selected_for_range.lock().unwrap();
            let (lo, hi) = (start.min(end), start.max(end));
            for (index, slot) in selected.iter_mut().enumerate() {
                *slot = index >= lo && index <= hi;
            }
            Ok(Value::Nil)
        });

        let picks_for_select = picks.clone();
        let selected_for_pick = selected.clone();
        runtime.register_native("seq-select-step", move |args, _ctx| {
            let Some(Value::Number(step)) = args.first() else {
                return Err("seq-select-step: expected step".into());
            };
            let step = *step as usize;
            picks_for_select.lock().unwrap().push(step);
            let mut selected = selected_for_pick.lock().unwrap();
            selected[step] = !selected[step];
            Ok(Value::Bool(selected[step]))
        });
    }

    struct StepGestureHarness {
        runtime: Runtime,
        steps: Arc<Mutex<Vec<bool>>>,
        toggles: Arc<Mutex<Vec<usize>>>,
        moves: Arc<Mutex<Vec<(usize, usize)>>>,
        ranges: Arc<Mutex<Vec<(usize, usize)>>>,
        picks: Arc<Mutex<Vec<usize>>>,
    }

    fn step_gesture_runtime(initial_steps: &[bool], selected_steps: &[bool]) -> StepGestureHarness {
        let steps = Arc::new(Mutex::new(initial_steps.to_vec()));
        let selected = Arc::new(Mutex::new(selected_steps.to_vec()));
        let toggles = Arc::new(Mutex::new(Vec::new()));
        let moves = Arc::new(Mutex::new(Vec::new()));
        let ranges = Arc::new(Mutex::new(Vec::new()));
        let picks = Arc::new(Mutex::new(Vec::new()));
        let clock = Arc::new(Mutex::new(0.0f64));
        let mut runtime = Runtime::new();
        runtime
            .eval_str(
                "(do (def cursor-step 0) (def eseq.seq-core-state/set-cursor-step-value (step) (set! cursor-step step)))",
            )
            .expect("define cursor step helpers");
        runtime
            .eval_str("(def step-key-select-anchor nil)")
            .expect("define keyboard anchor");
        runtime
            .eval_str(&format!(
                "(def SEQ (dict :current-track 0 :selected-steps '{}))",
                bool_list_source(selected_steps)
            ))
            .expect("define SEQ test map");
        register_step_gesture_test_natives(
            &mut runtime,
            steps.clone(),
            selected,
            toggles.clone(),
            moves.clone(),
            ranges.clone(),
            picks.clone(),
            clock,
        );
        load_step_gesture_source(&mut runtime);
        StepGestureHarness {
            runtime,
            steps,
            toggles,
            moves,
            ranges,
            picks,
        }
    }

    fn track_qualified_step_gesture_runtime() -> (
        Runtime,
        Arc<Mutex<Vec<Vec<bool>>>>,
        Arc<Mutex<Vec<(usize, usize)>>>,
    ) {
        let steps = Arc::new(Mutex::new(vec![
            vec![false, true, false, false],
            vec![false, false, false, false],
        ]));
        let current_track = Arc::new(Mutex::new(0usize));
        let toggles = Arc::new(Mutex::new(Vec::new()));
        let mut runtime = Runtime::new();
        runtime
            .eval_str(
                "(do (def cursor-step 0) (def eseq.seq-core-state/set-cursor-step-value (step) (set! cursor-step step)))",
            )
            .expect("define cursor step helpers");
        runtime
            .eval_str(
                "(def SEQ (dict :current-track 1 :selected-steps '(false false false false)))",
            )
            .expect("define stale SEQ test map");
        runtime.register_native("eseq.seq-core-state/cool-off-follow", |_args, _ctx| Ok(Value::Nil));
        runtime.register_native("seq-has-selection?", |_args, _ctx| Ok(Value::Bool(false)));
        runtime.register_native("seq-select-step-range", |_args, _ctx| Ok(Value::Nil));
        runtime.register_native("seq-select-step", |_args, _ctx| Ok(Value::Nil));
        runtime.register_native("seq-move-step-drag", |_args, _ctx| Ok(Value::Bool(true)));
        runtime.register_native("now-ms", |_args, _ctx| Ok(Value::Number(0.0)));
        {
            let current_track = current_track.clone();
            runtime.register_native("seq-set-track", move |args, _ctx| {
                let Some(Value::Number(track)) = args.first() else {
                    return Err("seq-set-track: expected track".into());
                };
                *current_track.lock().unwrap() = *track as usize;
                Ok(Value::Number(*track))
            });
        }
        {
            let steps = steps.clone();
            runtime.register_native("seq-track-step-active?", move |args, _ctx| {
                let (Some(Value::Number(track)), Some(Value::Number(step))) =
                    (args.first(), args.get(1))
                else {
                    return Err("seq-track-step-active?: expected track and step".into());
                };
                Ok(Value::Bool(
                    steps.lock().unwrap()[*track as usize][*step as usize],
                ))
            });
        }
        {
            let steps = steps.clone();
            let current_track = current_track.clone();
            let toggles = toggles.clone();
            runtime.register_native("seq-toggle-step", move |args, _ctx| {
                let Some(Value::Number(step)) = args.first() else {
                    return Err("seq-toggle-step: expected step".into());
                };
                let track = *current_track.lock().unwrap();
                let step = *step as usize;
                let mut steps = steps.lock().unwrap();
                steps[track][step] = !steps[track][step];
                toggles.lock().unwrap().push((track, step));
                Ok(Value::Bool(steps[track][step]))
            });
        }
        load_step_gesture_source(&mut runtime);
        (runtime, steps, toggles)
    }

    fn bool_list_source(values: &[bool]) -> String {
        let items = values
            .iter()
            .map(|value| if *value { "true" } else { "false" })
            .collect::<Vec<_>>()
            .join(" ");
        format!("({items})")
    }

