    fn browser_editor_on_instrument_tab() -> eseqlisp::Editor {
        let src = std::fs::read_to_string("ui/browser.lisp").expect("read browser lisp");
        let mut editor = eseqlisp::Editor::new(Runtime::new(), eseqlisp::EditorConfig::default());
        editor.runtime_mut().register_reactive(
            "SEQ",
            vec![
                ("num-tracks", Value::Number(0.0)),
                ("current-track", Value::Number(0.0)),
                ("song-bound-clip", Value::Nil),
                ("track-instrument-types", test_list(vec![])),
                // The real eseq.seq-core-state (imported by browser.lisp)
                // gates seq-has-selected-bus? on the bus list length.
                (
                    "bus-names",
                    test_list(vec![
                        Value::String("Bus A".to_string()),
                        Value::String("Bus B".to_string()),
                    ]),
                ),
                ("sidebar-kind", Value::String("sampler".to_string())),
                ("sidebar-track-index", Value::Number(0.0)),
                ("sidebar-selected-sample", Value::String(String::new())),
                ("sidebar-presets", test_list(vec![])),
                ("sidebar-loaded-preset", Value::String(String::new())),
                ("sidebar-instrument-name", Value::String(String::new())),
                ("project-instrument-engines", test_list(vec![])),
                (
                    "sound-presets",
                    test_list(vec![map_value([
                        ("kind", Value::String("sound".to_string())),
                        ("label", Value::String("Wide Plate".to_string())),
                        ("name", Value::String("Wide Plate".to_string())),
                        ("path", Value::String("sounds/wide-plate.sound".to_string())),
                    ])]),
                ),
                (
                    "kit-presets",
                    test_list(vec![map_value([
                        ("kind", Value::String("kit".to_string())),
                        ("label", Value::String("House Kit".to_string())),
                        ("name", Value::String("House Kit".to_string())),
                        ("path", Value::String("kits/House-Kit.kit".to_string())),
                    ])]),
                ),
                (
                    "sidebar-instrument-display-name",
                    Value::String(String::new()),
                ),
                ("instrument-panel", test_list(vec![])),
                ("current-project-name", Value::String(String::new())),
                ("editor-mode", Value::String(String::new())),
                ("editor-buffer-name", Value::String(String::new())),
                ("editor-canceling", Value::Bool(false)),
                ("editor-error", Value::String(String::new())),
                ("editor-active-macro-name", Value::String(String::new())),
                ("editor-active-macro-action", Value::String(String::new())),
                (
                    "editor-instrument-run-mode",
                    Value::String("instrument".to_string()),
                ),
            ],
            true,
        );
        editor
            .runtime_mut()
            .register_native("seq-filter-sample-tree", |_args, _ctx| {
                Ok(test_sample_tree())
            });
        editor
            .runtime_mut()
            .register_native(
                "seq-sample-browser",
                |_args, _ctx| Ok(test_sample_browser()),
            );
        editor
            .runtime_mut()
            .register_native("seq-sample-tags-for-path", |_args, _ctx| {
                Ok(test_list(
                    vec!["kick", "808"]
                        .into_iter()
                        .map(|tag| Value::String(tag.to_string()))
                        .collect(),
                ))
            });
        // Test paths never resolve to real WAVs; the production native answers
        // false for those, so the stub does the same.
        editor
            .runtime_mut()
            .register_native("seq-sample-waveform", |_args, _ctx| Ok(Value::Bool(false)));
        editor
            .runtime_mut()
            .register_native("seq-project-tree", |_args, _ctx| Ok(test_list(vec![])));
        editor
            .runtime_mut()
            .register_native("seq-script-tree", |args, _ctx| {
                let query = match args.first() {
                    Some(Value::String(s)) => s.as_str(),
                    _ => "",
                };
                Ok(build_script_tree(query))
            });
        editor
            .runtime_mut()
            .register_native("seq-preset-tree", |_args, _ctx| Ok(test_list(vec![])));
        editor
            .runtime_mut()
            .register_native("seq-audio-effect-tree", |_args, _ctx| Ok(test_list(vec![])));
        editor
            .runtime_mut()
            .register_native("seq-midi-effect-tree", |_args, _ctx| Ok(test_list(vec![])));
        editor
            .runtime_mut()
            .register_native("seq-saved-instrument-tree", |args, _ctx| {
                let query = match args.first() {
                    Some(Value::String(s)) => s.as_str(),
                    _ => "",
                };
                let project_engines = match args.get(1) {
                    Some(Value::List(items)) => items
                        .iter()
                        .filter_map(|item| match &*item.borrow() {
                            Value::String(name) => Some(name.clone()),
                            _ => None,
                        })
                        .collect::<Vec<_>>(),
                    _ => Vec::new(),
                };
                Ok(build_instrument_tree_value(query, &project_engines))
            });
        // selected-bus and seq-has-selected-bus? used to be stubbed flat here;
        // browser.lisp now imports eseq.seq-core-state, whose compile-time
        // half (spec §4) evaluates the real module before browser's readers
        // compile, so the test's bare `(set! selected-bus …)` resolves through
        // the module's compat alias to the real binding.
        // ui/track-collapse.lisp is a module now, and its compat aliases only
        // reach callers compiled after it is evaluated — this harness evals
        // the consumer's source directly, so the dep has to be a separate,
        // earlier eval (the consumer's own top-of-file `load` runs too late).
        editor
            .runtime_mut()
            .eval_str("(load \"ui/track-collapse.lisp\")")
            .expect("load track-collapse module");
        editor
            .runtime_mut()
            .eval_str(&src)
            .expect("load browser lisp");
        editor
            .runtime_mut()
            .eval_str("(set! sbrowser-tab \"instruments\")")
            .expect("select instrument tab");
        editor.refresh_runtime_side_effects();
        if let Some(status) = editor.runtime_mut().take_status_message() {
            panic!("browser lisp status after refresh: {status}");
        }
        editor
    }

    fn browser_id(editor: &eseqlisp::Editor) -> eseqlisp::host::BufferId {
        editor
            .buffers
            .iter()
            .find(|buffer| buffer.name == "*samples*")
            .expect("browser lisp should create the *samples* buffer")
            .id
    }

