    fn find_layout_node_by_stable_key<'a>(
        node: &'a eseqlisp::layout::LayoutNode,
        key: &str,
    ) -> Option<&'a eseqlisp::layout::LayoutNode> {
        if node.stable_key.as_deref() == Some(key) {
            return Some(node);
        }
        node.children
            .iter()
            .find_map(|child| find_layout_node_by_stable_key(child, key))
    }

    /// Module-system migration helper (module-system spec §10 hazard a).
    ///
    /// Widget `:key`s auto-qualify inside a declared module, so converting
    /// `ui/sequencer.lisp` re-keys `"track-row-0"` to
    /// `"eseq.sequencer/track-row-0"` and every exact-match assertion in this
    /// file breaks at once. A converted file's assertions rewrite to the
    /// `/`-prefixed suffix (`"/track-row-0"`), which pins the key without
    /// naming the owning module — so a later module rename, or moving the
    /// widget between modules, does not churn hundreds of assertions again.
    /// Keep the leading `/`: a bare suffix would also match an unrelated key
    /// that merely ends with the same characters.
    ///
    /// Note the suffix form matches the **qualified** key only, so an
    /// assertion migrates *with* its file's conversion, not before it. This
    /// is not a mass migration: each of the four remaining big files rewrites
    /// its own assertions as it converts (a bulk rewrite would bury the
    /// conversion diffs). Deliberately duplicated from `ui/tests.rs` rather
    /// than hoisted into a shared module — that is the existing pattern for
    /// these layout probes (`find_layout_node_by_stable_key` itself lives in
    /// both files), and both `mod tests` blocks are private.
    fn find_layout_node_by_stable_key_suffix<'a>(
        node: &'a eseqlisp::layout::LayoutNode,
        suffix: &str,
    ) -> Option<&'a eseqlisp::layout::LayoutNode> {
        if node
            .stable_key
            .as_deref()
            .is_some_and(|key| key.ends_with(suffix))
        {
            return Some(node);
        }
        node.children
            .iter()
            .find_map(|child| find_layout_node_by_stable_key_suffix(child, suffix))
    }

    /// `collect_layout_nodes_by_stable_key` for a module-qualified key — the
    /// collecting twin of `find_layout_node_by_stable_key_suffix`, same
    /// leading-`/` convention.
    fn collect_layout_nodes_by_stable_key_suffix<'a>(
        node: &'a eseqlisp::layout::LayoutNode,
        suffix: &str,
        out: &mut Vec<&'a eseqlisp::layout::LayoutNode>,
    ) {
        if node
            .stable_key
            .as_deref()
            .is_some_and(|key| key.ends_with(suffix))
        {
            out.push(node);
        }
        for child in &node.children {
            collect_layout_nodes_by_stable_key_suffix(child, suffix, out);
        }
    }

    fn collect_layout_nodes_by_stable_key<'a>(
        node: &'a eseqlisp::layout::LayoutNode,
        key: &str,
        out: &mut Vec<&'a eseqlisp::layout::LayoutNode>,
    ) {
        if node.stable_key.as_deref() == Some(key) {
            out.push(node);
        }
        for child in &node.children {
            collect_layout_nodes_by_stable_key(child, key, out);
        }
    }

    fn layout_prop_bool(node: &eseqlisp::layout::LayoutNode, prop: &str) -> Option<bool> {
        match node.props.get(prop)? {
            Value::Bool(value) => Some(*value),
            Value::Number(value) => Some(*value != 0.0),
            Value::ReactiveRef { slot, .. } => {
                Some(eseqlisp::reactive::read_float_slot(slot) != 0.0)
            }
            _ => None,
        }
    }

    fn layout_prop_number(node: &eseqlisp::layout::LayoutNode, prop: &str) -> Option<f64> {
        match node.props.get(prop)? {
            Value::Number(value) => Some(*value),
            Value::ReactiveRef { slot, .. } => {
                Some(eseqlisp::reactive::read_float_slot(slot) as f64)
            }
            _ => None,
        }
    }

    fn assert_layout_rgba_prop(
        node: &eseqlisp::layout::LayoutNode,
        prop: &str,
        expected: [f64; 4],
    ) {
        let value = node
            .props
            .get(prop)
            .unwrap_or_else(|| panic!("missing {prop} on {}", node.widget_type));
        let Value::List(items) = value else {
            panic!("expected {prop} to be an rgba expression, got {value:?}");
        };
        assert_eq!(
            items.len(),
            5,
            "rgba expression should have 5 items: {value:?}"
        );
        assert_eq!(*items[0].borrow(), Value::Symbol("rgba".to_string()));
        for (idx, expected_component) in expected.into_iter().enumerate() {
            let Value::Number(component) = *items[idx + 1].borrow() else {
                panic!("rgba component {idx} should be numeric: {value:?}");
            };
            assert!(
                (component - expected_component).abs() < 0.0001,
                "rgba component {idx} should be {expected_component}, got {component}: {value:?}"
            );
        }
    }

    fn layout_tree_has_bool_prop(
        node: &eseqlisp::layout::LayoutNode,
        prop: &str,
        expected: bool,
    ) -> bool {
        layout_prop_bool(node, prop) == Some(expected)
            || node
                .children
                .iter()
                .any(|child| layout_tree_has_bool_prop(child, prop, expected))
    }

    fn layout_tree_has_reactive_prop_field(
        node: &eseqlisp::layout::LayoutNode,
        prop: &str,
        namespace: &str,
        field: &str,
    ) -> bool {
        matches!(
            node.props.get(prop),
            Some(Value::ReactiveRef {
                namespace: actual_namespace,
                field: actual_field,
                ..
            }) if actual_namespace == namespace && actual_field == field
        ) || node
            .children
            .iter()
            .any(|child| layout_tree_has_reactive_prop_field(child, prop, namespace, field))
    }

    fn render_layout_cells(layout: &eseqlisp::layout::LayoutNode, cols: u16, rows: u16) -> String {
        let mut cell_buf = eseqlisp::widget_render::CellBuffer::new(cols, rows);
        eseqlisp::widget_render::render_widget_tree(layout, &mut cell_buf);
        cell_buf
            .cells
            .iter()
            .map(|row| {
                row.iter()
                    .map(|cell| cell.as_ref().map(|cell| cell.ch).unwrap_or(' '))
                    .collect::<String>()
            })
            .collect::<Vec<_>>()
            .join("\n")
    }

    fn find_layout_text_containing<'a>(
        node: &'a eseqlisp::layout::LayoutNode,
        needle: &str,
    ) -> Option<&'a eseqlisp::layout::LayoutNode> {
        if matches!(node.props.get("text"), Some(Value::String(text)) if text.contains(needle)) {
            return Some(node);
        }
        if matches!(node.props.get("label"), Some(Value::String(text)) if text.contains(needle)) {
            return Some(node);
        }
        node.children
            .iter()
            .find_map(|child| find_layout_text_containing(child, needle))
    }

    fn top_level_tree_field_strings(value: &Value, field: &str) -> Vec<Option<String>> {
        let Value::List(items) = value else {
            panic!("tree should be a list: {value:?}");
        };
        items
            .iter()
            .map(|item| {
                let item = item.borrow();
                let Value::Map(map) = &*item else {
                    return None;
                };
                value_map_string(map, field)
            })
            .collect()
    }

    fn top_level_tree_field_bools(value: &Value, field: &str) -> Vec<Option<bool>> {
        let Value::List(items) = value else {
            panic!("tree should be a list: {value:?}");
        };
        items
            .iter()
            .map(|item| {
                let item = item.borrow();
                let Value::Map(map) = &*item else {
                    return None;
                };
                map.get(field).and_then(|value| match &*value.borrow() {
                    Value::Bool(value) => Some(*value),
                    _ => None,
                })
            })
            .collect()
    }

    fn tree_contains_kind(value: &Value, expected_kind: &str) -> bool {
        match value {
            Value::Map(map) => {
                if value_map_string(map, "kind").as_deref() == Some(expected_kind) {
                    return true;
                }
                map.get("children")
                    .is_some_and(|children| tree_contains_kind(&children.borrow(), expected_kind))
            }
            Value::List(items) => items
                .iter()
                .any(|item| tree_contains_kind(&item.borrow(), expected_kind)),
            _ => false,
        }
    }

