    #[test]
    fn metal_seq_browser_samples_only_activation_chooses_learn_target() {
        let mut editor = browser_editor_on_instrument_tab();
        editor
            .runtime_mut()
            .eval_str(
                r#"(eseq.browser/%choose-learn-target
                    (dict :label "Acoustic Kick 808" :path "samples/abc123.wav"))"#,
            )
            .expect("choose patch-learning target");

        let commands = editor.drain_host_commands();
        assert_eq!(commands.len(), 1);
        match &commands[0] {
            eseqlisp::host::HostCommand::Custom { name, payload } => {
                assert_eq!(name, "set-learn-target");
                let Value::Map(payload) = payload else {
                    panic!("learn-target payload should be a dict: {payload:?}");
                };
                assert_eq!(
                    payload.get("path").map(|value| value.borrow().clone()),
                    Some(Value::String("samples/abc123.wav".to_string()))
                );
                assert_eq!(
                    payload.get("name").map(|value| value.borrow().clone()),
                    Some(Value::String("Acoustic Kick 808".to_string()))
                );
            }
            other => panic!("expected set-learn-target host command, got {other:?}"),
        }

        let picker = editor
            .runtime_mut()
            .eval_str(r#"(eseq.browser/sample-browser-widget true "" "")"#)
            .expect("build samples-only picker")
            .expect("samples-only picker value");
        assert!(
            value_contains_string(&picker, "learn-target-samples-tree"),
            "samples-only mode should render the shared sample tree"
        );
        assert!(
            !value_contains_string(&picker, "Instruments")
                && !value_contains_string(&picker, "Sounds"),
            "samples-only mode must not expose non-sample tabs"
        );

        let selected = editor
            .runtime_mut()
            .eval_str(
                r#"(eseq.browser/sample-browser-widget
                    true
                    "samples/72a634c18e3035e7526edd85d31cb675806a3834b48ed7c53d8.wav"
                    "Tim Maia – Est Dificil (Original Studio Recording 1971)")"#,
            )
            .expect("build selected target row")
            .expect("selected target row value");
        assert!(value_contains_string(
            &selected,
            "Tim Maia – Est Dificil (Origi…"
        ));
        assert!(!value_contains_string(
            &selected,
            "72a634c18e3035e7526edd85d31cb675806a3834b48ed7c53d8.wav"
        ));
        assert!(value_contains_string(&selected, "Change"));
        assert!(!value_contains_string(&selected, "learn-target-samples-tree"));
    }

    #[test]
    fn metal_seq_browser_cursor_auto_previews_with_headphone_toggle() {
        let mut editor = browser_editor_on_instrument_tab();
        editor
            .runtime_mut()
            .set_reactive("SEQ", "num-tracks", Value::Number(1.0));
        // The fixture's seq-sample-waveform stub answers false (undecodable);
        // this test needs a decodable sample, so override it with a buffer map.
        editor
            .runtime_mut()
            .register_native("seq-sample-waveform", |args, _ctx| {
                let path = match args.first() {
                    Some(Value::String(path)) => path.clone(),
                    _ => String::new(),
                };
                Ok(map_value([
                    ("path", Value::String(path)),
                    ("duration", Value::Number(1.0)),
                ]))
            });

        // Headphone defaults off: landing on a sample tracks it silently.
        editor
            .runtime_mut()
            .eval_str(
                r#"(eseq.browser/select-sample
                    (dict :label "kick.wav" :path "samples/kick.wav"))"#,
            )
            .expect("cursor onto sample");
        assert!(
            editor.drain_host_commands().is_empty(),
            "cursor moves with the headphone off should not play anything"
        );
        assert_eq!(
            editor
                .runtime_mut()
                .eval_str("eseq.browser/%preview-path")
                .expect("read preview path"),
            Some(Value::String("samples/kick.wav".to_string()))
        );

        // Toggling the headphone on auditions the focused sample...
        editor
            .runtime_mut()
            .eval_str("(eseq.browser/%toggle-auto-preview)")
            .expect("headphone on");
        let commands = editor.drain_host_commands();
        assert_eq!(commands.len(), 1);
        match &commands[0] {
            eseqlisp::host::HostCommand::Custom { name, payload } => {
                assert_eq!(name, "preview-sample");
                let Value::Map(payload) = payload else {
                    panic!("preview payload should be a dict: {payload:?}");
                };
                assert_eq!(
                    payload.get("path").map(|value| value.borrow().clone()),
                    Some(Value::String("samples/kick.wav".to_string()))
                );
            }
            other => panic!("expected preview-sample host command, got {other:?}"),
        }

        // ...and cursor moves now auto-play each sample once.
        editor
            .runtime_mut()
            .eval_str(
                r#"(eseq.browser/select-sample
                    (dict :label "snare.wav" :path "samples/snare.wav"))"#,
            )
            .expect("cursor onto another sample");
        let commands = editor.drain_host_commands();
        assert_eq!(commands.len(), 1);
        match &commands[0] {
            eseqlisp::host::HostCommand::Custom { name, payload } => {
                assert_eq!(name, "preview-sample");
                let Value::Map(payload) = payload else {
                    panic!("preview payload should be a dict: {payload:?}");
                };
                assert_eq!(
                    payload.get("path").map(|value| value.borrow().clone()),
                    Some(Value::String("samples/snare.wav".to_string()))
                );
            }
            other => panic!("expected preview-sample host command, got {other:?}"),
        }

        // Toggling the headphone off stops the preview still in flight.
        editor
            .runtime_mut()
            .set_reactive("SEQ", "browser-preview-playing", Value::Bool(true));
        editor
            .runtime_mut()
            .eval_str("(eseq.browser/%toggle-auto-preview)")
            .expect("headphone off");
        let commands = editor.drain_host_commands();
        assert_eq!(commands.len(), 1);
        match &commands[0] {
            eseqlisp::host::HostCommand::Custom { name, .. } => {
                assert_eq!(name, "stop-sample-preview");
            }
            other => panic!("expected stop-sample-preview host command, got {other:?}"),
        }
    }

