    fn test_bool_list(values: &[bool]) -> Value {
        test_list(values.iter().copied().map(Value::Bool).collect())
    }

    fn bool_list_values(value: &Value) -> Vec<bool> {
        match value {
            Value::List(items) => items
                .iter()
                .map(|item| match &*item.borrow() {
                    Value::Bool(value) => *value,
                    other => panic!("expected bool list item, got {other:?}"),
                })
                .collect(),
            other => panic!("expected bool list, got {other:?}"),
        }
    }

    fn number_list_values(value: &Value) -> Vec<f64> {
        match value {
            Value::List(items) => items
                .iter()
                .map(|item| match &*item.borrow() {
                    Value::Number(value) => *value,
                    other => panic!("expected number list item, got {other:?}"),
                })
                .collect(),
            other => panic!("expected number list, got {other:?}"),
        }
    }

    fn assert_number_lists_close(actual: &[f64], expected: &[f64]) {
        assert_eq!(actual.len(), expected.len());
        for (idx, (actual, expected)) in actual.iter().zip(expected.iter()).enumerate() {
            assert!(
                (actual - expected).abs() < 0.000001,
                "value {idx} expected {expected}, got {actual}"
            );
        }
    }

    fn string_list_values(value: &Value) -> Vec<String> {
        match value {
            Value::List(items) => items
                .iter()
                .map(|item| match &*item.borrow() {
                    Value::String(value) => value.clone(),
                    other => panic!("expected string list item, got {other:?}"),
                })
                .collect(),
            other => panic!("expected string list, got {other:?}"),
        }
    }

    fn reactive_field_value(runtime: &Runtime, namespace: &str, field: &str) -> Value {
        let Some(Value::Map(map)) = runtime.global_value(namespace) else {
            panic!("missing reactive namespace {namespace}");
        };
        let value = map
            .get(field)
            .unwrap_or_else(|| panic!("missing reactive field {namespace}.{field}"))
            .borrow()
            .clone();
        value
    }

    fn assert_effective_color_reactives_match_builders(
        runtime: &Runtime,
        app: &app::App,
        state: &Arc<SequencerState>,
    ) {
        for channel in 0..3 {
            for (field, expected) in [
                (
                    track_color_channel_effective_field(channel),
                    build_track_color_channel_effective(app, state, channel),
                ),
                (
                    step_color_channel_effective_field(channel),
                    build_step_color_channel_effective(app, state, channel),
                ),
            ] {
                let actual = number_list_values(&reactive_field_value(runtime, "SEQ", field));
                assert_number_lists_close(&actual, &number_list_values(&expected));
            }
        }
    }

    fn test_app_for_track_visual_state(state: Arc<SequencerState>) -> app::App {
        let (keyboard_tx, _keyboard_rx) = std::sync::mpsc::channel();
        let mut app = app::App::new(
            state.clone(),
            sequencer::audiograph::LiveGraphPtr(std::ptr::null_mut()),
            44_100,
            app::AudioBuses {
                bus_l_id: 0,
                bus_r_id: 0,
                default_bus_nodes: Vec::new(),
                bus_gate_runtime: Arc::new(Mutex::new(Arc::new(Vec::new()))),
                bus_gate_playheads: Arc::new(Mutex::new(Vec::new())),
                reverb_bus_id: 0,
                reverb_node_id: 0,
            },
            Arc::new(sequencer::recorder::MasterRecorder::new(44_100, 2)),
            keyboard_tx,
        );
        app.tracks = (0..state.active_track_count())
            .map(|track| format!("Track {}", track + 1))
            .collect();
        app.track_registry = sequencer::sequencer::TrackRegistry::for_legacy_track_count(
            state.active_track_count(),
        )
        .unwrap();
        app
    }

    #[test]
    fn selected_step_bus_send_binding_displays_lock_and_restores_baseline_on_deselect() {
        let state = Arc::new(SequencerState::new(1, vec![]));
        let app = test_app_for_track_visual_state(state.clone());
        let destination = sequencer::sequencer::BusId::DEFAULT_A;
        let bus_idx = app.buses.iter().position(|bus| bus.id == destination)
            .expect("default send bus");
        state.pattern.track_params[0].set_sends(vec![
            sequencer::sequencer::TrackSendSnapshot { destination, amount: 0.2 },
        ]);
        state.pattern.track_send_plocks[0].set(4, destination, 0.8);
        let selected = Arc::new(Mutex::new(HashSet::from([4])));
        let mut runtime = Runtime::new();
        runtime.register_reactive("SEQ", vec![], false);

        sync_selected_track_bus_send_binding_fields(
            &mut runtime,
            &app,
            &state,
            0,
            &selected,
        );
        assert_eq!(
            reactive_field_value(&runtime, "SEQ", &track_bus_send_field(0, bus_idx)),
            Value::Number(0.8_f32 as f64),
        );
        assert_eq!(
            reactive_field_value(&runtime, "SEQ", &current_track_bus_send_field(bus_idx)),
            Value::Number(0.8_f32 as f64),
        );

        selected.lock().unwrap().clear();
        sync_selected_track_bus_send_binding_fields(
            &mut runtime,
            &app,
            &state,
            0,
            &selected,
        );
        assert_eq!(
            reactive_field_value(&runtime, "SEQ", &current_track_bus_send_field(bus_idx)),
            Value::Number(0.2_f32 as f64),
        );

        state.transport.playing.store(true, Ordering::Relaxed);
        state.transport.track_playheads[0].store(4, Ordering::Relaxed);
        sync_selected_track_bus_send_binding_fields(
            &mut runtime,
            &app,
            &state,
            0,
            &selected,
        );
        assert_eq!(
            reactive_field_value(&runtime, "SEQ", &current_track_bus_send_field(bus_idx)),
            Value::Number(0.8_f32 as f64),
        );
        state.transport.track_playheads[0].store(5, Ordering::Relaxed);
        sync_selected_track_bus_send_binding_fields(
            &mut runtime,
            &app,
            &state,
            0,
            &selected,
        );
        assert_eq!(
            reactive_field_value(&runtime, "SEQ", &current_track_bus_send_field(bus_idx)),
            Value::Number(0.2_f32 as f64),
        );
    }

