    #[test]
    fn instrument_panel_restores_value_field_after_selection_clears() {
        let desc = sequencer::effects::EffectDescriptor::builtin_filter();
        let cutoff_idx = desc
            .params
            .iter()
            .position(|param| param.name == "cutoff")
            .expect("filter descriptor should include cutoff");
        let app = test_app_with_instrument_descriptor(desc.clone());
        app.state.pattern.instrument_slots[0]
            .defaults
            .set(cutoff_idx, 5000.0);
        app.state.pattern.instrument_slots[0].set_plock(3, cutoff_idx, 1200.0);
        let selected_steps = Arc::new(Mutex::new(HashSet::new()));
        let value_field =
            instrument_param_value_field(0, cutoff_idx, &desc.params[cutoff_idx].name);

        let default_panel = build_instrument_panel_value(&app, 0, &selected_steps);
        assert_eq!(
            value_param_number(&default_panel, "cutoff"),
            Some(5000.0),
            "unselected instrument panel should show the default value"
        );
        assert!(
            value_param_has_value_field(&default_panel, "cutoff", &value_field),
            "unselected instrument panel should bind cutoff to its default value field"
        );

        selected_steps.lock().unwrap().insert(3);
        let selected_panel = build_instrument_panel_value(&app, 0, &selected_steps);
        assert_eq!(
            value_param_number(&selected_panel, "cutoff"),
            Some(1200.0),
            "selected instrument panel should show the selected step p-lock"
        );
        assert!(
            value_param_has_value_field(&selected_panel, "cutoff", &value_field),
            "selected p-lock panel should keep a reactive display value field"
        );

        selected_steps.lock().unwrap().clear();
        let cleared_panel = build_instrument_panel_value(&app, 0, &selected_steps);
        assert_eq!(
            value_param_number(&cleared_panel, "cutoff"),
            Some(5000.0),
            "cleared selection should return the panel to default values"
        );
        assert!(
            value_param_has_value_field(&cleared_panel, "cutoff", &value_field),
            "cleared selection should restore default value binding"
        );
    }

    #[test]
    fn instrument_panel_exposes_tensor_params_and_selected_step_matrix_value() {
        fn tensor_map_owned(value: &Value, name: &str) -> Option<HashMap<String, Value>> {
            match value {
                Value::Map(map) => {
                    if value_map_string(map, "name").as_deref() == Some(name)
                        && map.contains_key("rows")
                        && map.contains_key("cols")
                    {
                        return Some(
                            map.iter()
                                .map(|(key, value)| (key.clone(), value.borrow().clone()))
                                .collect(),
                        );
                    }
                    map.values()
                        .find_map(|value| tensor_map_owned(&value.borrow(), name))
                }
                Value::List(items) => items
                    .iter()
                    .find_map(|value| tensor_map_owned(&value.borrow(), name)),
                _ => None,
            }
        }

        fn number_list(value: &Value) -> Vec<f64> {
            let Value::List(items) = value else {
                panic!("expected number list, got {value:?}");
            };
            items
                .iter()
                .map(|value| match &*value.borrow() {
                    Value::Number(value) => *value,
                    other => panic!("expected number, got {other:?}"),
                })
                .collect()
        }

        fn assert_numbers_close(actual: Vec<f64>, expected: &[f64]) {
            assert_eq!(actual.len(), expected.len());
            for (idx, (actual, expected)) in actual.iter().zip(expected.iter()).enumerate() {
                assert!(
                    (actual - expected).abs() < 0.000001,
                    "value {idx} expected {expected}, got {actual}"
                );
            }
        }

        let desc = sequencer::effects::EffectDescriptor {
            name: "tensor instrument".to_string(),
            input_channels: 0,
            output_channels: 2,
            instrument_modulators: Vec::new(),
            instrument_modulation_targets: Vec::new(),
            tensor_params: vec![sequencer::effects::TensorParamDescriptor {
                name: "strike_mask".to_string(),
                shape: vec![2, 2],
                cell_offset: 64,
                default: vec![0.1, 0.2, 0.3, 0.4],
                min: 0.0,
                max: 1.0,
            }],
            params: Vec::new(),
        };
        let mut app = test_app_with_instrument_descriptor(desc);
        app.graph.track_instrument_types = vec![sequencer::sequencer::InstrumentType::Custom];
        app.state.pattern.instrument_slots[0]
            .tensor_params
            .set_plock_cell(5, 0, 2, 0.95)
            .expect("tensor p-lock edit");
        let selected_steps = Arc::new(Mutex::new(HashSet::new()));
        let field = instrument_tensor_value_field(0, 0, "strike_mask");

        let default_panel = build_instrument_panel_value(&app, 0, &selected_steps);
        let tensor = tensor_map_owned(&default_panel, "strike_mask").expect("tensor panel map");
        assert_eq!(tensor.get("idx"), Some(&Value::Number(0.0)));
        assert_eq!(tensor.get("rows"), Some(&Value::Number(2.0)));
        assert_eq!(tensor.get("cols"), Some(&Value::Number(2.0)));
        assert_eq!(tensor.get("min"), Some(&Value::Number(0.0)));
        assert_eq!(tensor.get("max"), Some(&Value::Number(1.0)));
        assert_eq!(
            tensor.get("value-field"),
            Some(&Value::String(field.clone()))
        );
        assert_numbers_close(
            number_list(tensor.get("value").expect("tensor value")),
            &[0.1, 0.2, 0.3, 0.4],
        );

        selected_steps.lock().unwrap().insert(5);
        let selected_panel = build_instrument_panel_value(&app, 0, &selected_steps);
        let selected_tensor =
            tensor_map_owned(&selected_panel, "strike_mask").expect("selected tensor panel map");
        assert_numbers_close(
            number_list(selected_tensor.get("value").expect("selected tensor value")),
            &[0.1, 0.2, 0.95, 0.4],
        );

        let mut runtime = Runtime::new();
        sync_instrument_tensor_value_field(&mut runtime, &app, 0, 0, Some(5));
        let Value::Map(seq) = runtime.global_value("SEQ").expect("SEQ namespace") else {
            panic!("SEQ should be a map");
        };
        let reactive_value = seq
            .get(&field)
            .unwrap_or_else(|| panic!("missing tensor field {field}"))
            .borrow()
            .clone();
        assert_numbers_close(number_list(&reactive_value), &[0.1, 0.2, 0.95, 0.4]);
    }

    #[test]
    fn sampler_panel_restores_value_field_after_selection_clears() {
        let desc = sequencer::effects::EffectDescriptor::builtin_sampler();
        let attack_idx = desc
            .params
            .iter()
            .position(|param| param.name == "attack")
            .expect("sampler descriptor should include attack");
        let app = test_app_with_sampler_descriptor(desc.clone());
        app.state.pattern.instrument_slots[0]
            .defaults
            .set(attack_idx, 40.0);
        app.state.pattern.instrument_slots[0].set_plock(3, attack_idx, 120.0);
        let selected_steps = Arc::new(Mutex::new(HashSet::new()));
        let value_field =
            instrument_param_value_field(0, attack_idx, &desc.params[attack_idx].name);

        let default_panel = build_instrument_panel_value(&app, 0, &selected_steps);
        assert_eq!(
            value_param_number_by_idx(&default_panel, "attack", attack_idx),
            Some(40.0),
            "unselected sampler panel should show the default attack value"
        );
        assert!(
            value_param_has_value_field_by_idx(&default_panel, "attack", attack_idx, &value_field),
            "unselected sampler panel should bind attack to its default value field"
        );

        selected_steps.lock().unwrap().insert(3);
        let selected_panel = build_instrument_panel_value(&app, 0, &selected_steps);
        assert_eq!(
            value_param_number_by_idx(&selected_panel, "attack", attack_idx),
            Some(120.0),
            "selected sampler panel should show the selected step p-lock"
        );
        assert!(
            value_param_has_value_field_by_idx(&selected_panel, "attack", attack_idx, &value_field),
            "selected sampler p-lock panel should keep a reactive display value field"
        );

        selected_steps.lock().unwrap().clear();
        let cleared_panel = build_instrument_panel_value(&app, 0, &selected_steps);
        assert_eq!(
            value_param_number_by_idx(&cleared_panel, "attack", attack_idx),
            Some(40.0),
            "cleared selection should return sampler attack to its default value"
        );
        assert!(
            value_param_has_value_field_by_idx(&cleared_panel, "attack", attack_idx, &value_field),
            "cleared selection should restore sampler attack default value binding"
        );
    }

    fn test_app_with_instrument_descriptor(desc: sequencer::effects::EffectDescriptor) -> app::App {
        let state = Arc::new(SequencerState::new(1, vec![vec![]]));
        state.pattern.instrument_slots[0].apply_descriptor(&desc, 0);
        let (keyboard_tx, _keyboard_rx) = std::sync::mpsc::channel();
        let mut app = app::App::new(
            state,
            sequencer::audiograph::LiveGraphPtr(std::ptr::null_mut()),
            44_100,
            app::AudioBuses {
                bus_l_id: 0,
                bus_r_id: 0,
                default_bus_nodes: Vec::new(),
                bus_gate_runtime: Arc::new(Mutex::new(Arc::new(Vec::new()))),
                bus_gate_playheads: Arc::new(Mutex::new(Vec::new())),
                reverb_bus_id: 0,
                reverb_node_id: 0,
            },
            Arc::new(sequencer::recorder::MasterRecorder::new(44_100, 2)),
            keyboard_tx,
        );
        app.tracks = vec!["Track 1".to_string()];
        app.track_registry =
            sequencer::sequencer::TrackRegistry::for_legacy_track_count(1).unwrap();
        app.graph.instrument_descriptors = vec![desc];
        app
    }

    #[test]
    fn macro_readback_exposes_definition_mapping_range_curve_and_current_value() {
        let desc = sequencer::effects::EffectDescriptor::builtin_sampler();
        let mut app = test_app_with_instrument_descriptor(desc.clone());
        app.state.pattern.instrument_slots[0].defaults.set(0, 17.5);
        let id = app
            .macro_engine
            .ensure_macro("player/push", "Push")
            .expect("macro id");
        app.macro_engine
            .add_mapping(
                id,
                sequencer::macro_engine::MacroMapping::new_resolved(
                    0,
                    sequencer::process::ParamTarget::InstrumentParam {
                        param: desc.params[0].name.clone(),
                        param_id: None,
                    },
                    Some(0),
                    desc.params[0].min,
                    desc.params[0].max,
                    sequencer::macro_engine::MacroCurve::Log,
                )
                .expect("mapping"),
            )
            .expect("known macro");

        let macros = value_list_maps(&build_macros_value(&app));
        assert_eq!(macros.len(), 1);
        assert!(matches!(
            &*macros[0]["id"].borrow(),
            Value::Number(value) if *value == id as f64
        ));
        assert!(matches!(
            &*macros[0]["name"].borrow(),
            Value::String(value) if value == "Push"
        ));
        assert!(matches!(
            &*macros[0]["key"].borrow(),
            Value::String(value) if value == "player/push"
        ));
        let mappings = value_list_maps(&macros[0]["mappings"].borrow());
        assert_eq!(mappings.len(), 1);
        assert!(matches!(
            &*mappings[0]["curve"].borrow(),
            Value::String(value) if value == "log"
        ));
        assert!(matches!(
            &*mappings[0]["current"].borrow(),
            Value::Number(value) if (*value - desc.params[0].min as f64).abs() < 1.0e-6
        ));
        assert!(matches!(
            &*mappings[0]["min"].borrow(),
            Value::Number(value) if *value == desc.params[0].min as f64
        ));
        assert!(matches!(
            &*mappings[0]["max"].borrow(),
            Value::Number(value) if *value == desc.params[0].max as f64
        ));
        assert!(matches!(
            &*mappings[0]["mapping-idx"].borrow(),
            Value::Number(value) if *value == 0.0
        ));
        assert!(matches!(
            &*mappings[0]["track"].borrow(),
            Value::Number(value) if *value == 0.0
        ));
        let target_cell = mappings[0]["target"].borrow();
        let Value::Map(target) = &*target_cell else {
            panic!("macro mapping target should be a map");
        };
        assert!(matches!(
            &*target["kind"].borrow(),
            Value::String(value) if value == "instrument"
        ));
        assert!(matches!(
            &*target["param"].borrow(),
            Value::String(value) if value == &desc.params[0].name
        ));
        assert!(matches!(
            &*mappings[0]["path-label"].borrow(),
            Value::String(value) if value.contains("Sampler")
        ));
        assert!(matches!(
            &*mappings[0]["param-label"].borrow(),
            Value::String(value) if value == &desc.params[0].name
        ));
        assert!(matches!(
            &*mappings[0]["domain-min"].borrow(),
            Value::Number(value) if *value == desc.params[0].stored_to_user(desc.params[0].min) as f64
        ));
    }

    #[test]
    fn macro_effective_values_are_published_to_instrument_and_effect_controls() {
        let instrument_desc = sequencer::effects::EffectDescriptor::builtin_sampler();
        let mut instrument_app = test_app_with_instrument_descriptor(instrument_desc.clone());
        let instrument_id = instrument_app
            .macro_engine
            .create_macro("instrument", sequencer::macro_engine::MacroKind::Mapped)
            .expect("instrument macro");
        instrument_app
            .macro_engine
            .add_mapping(
                instrument_id,
                sequencer::macro_engine::MacroMapping::new_resolved(
                    0,
                    sequencer::process::ParamTarget::InstrumentParam {
                        param: instrument_desc.params[0].name.clone(),
                        param_id: None,
                    },
                    Some(0),
                    10.0,
                    30.0,
                    sequencer::macro_engine::MacroCurve::Linear,
                )
                .expect("instrument mapping"),
            )
            .expect("unique instrument owner");
        instrument_app.set_macro_value(instrument_id, 0.5);
        let mut runtime = Runtime::new();
        sync_instrument_param_value_field(&mut runtime, &instrument_app, 0, 0, None);
        let instrument_field = instrument_param_value_field(0, 0, &instrument_desc.params[0].name);
        assert_eq!(
            reactive_number(&runtime, "SEQ", &instrument_field),
            Some(20.0)
        );
        sync_instrument_param_value_field(&mut runtime, &instrument_app, 0, 0, Some(4));
        assert_eq!(
            reactive_number(&runtime, "SEQ", &instrument_field),
            Some(20.0),
            "a playing step without a p-lock must display the macro-effective value"
        );
        instrument_app.state.pattern.instrument_slots[0].set_plock(4, 0, 25.0);
        sync_instrument_param_value_field(&mut runtime, &instrument_app, 0, 0, Some(4));
        assert_eq!(
            reactive_number(&runtime, "SEQ", &instrument_field),
            Some(25.0),
            "an explicit playing-step p-lock must remain visible above the macro"
        );
        instrument_app.set_macro_value(instrument_id, 0.0);
        sync_instrument_param_value_field(&mut runtime, &instrument_app, 0, 0, None);
        assert_eq!(
            reactive_number(&runtime, "SEQ", &instrument_field),
            Some(10.0),
            "continuous macro zero must display its mapped minimum, not the stored base"
        );

        let effect_desc = sequencer::effects::EffectDescriptor::builtin_filter();
        let effect_state = Arc::new(SequencerState::new(
            1,
            vec![vec![sequencer::effects::EffectSlotState::new(
                &effect_desc,
                0,
            )]],
        ));
        let mut effect_app = test_app_for_track_visual_state(Arc::clone(&effect_state));
        effect_app.graph.effect_descriptors = vec![vec![effect_desc.clone()]];
        let effect_id = effect_app
            .macro_engine
            .create_macro("effect", sequencer::macro_engine::MacroKind::Mapped)
            .expect("effect macro");
        effect_app
            .macro_engine
            .add_mapping(
                effect_id,
                sequencer::macro_engine::MacroMapping::new_resolved(
                    0,
                    sequencer::process::ParamTarget::EffectParam {
                        slot: 0,
                        effect: effect_desc.name.clone(),
                        param: effect_desc.params[0].name.clone(),
                        param_id: None,
                    },
                    Some(0),
                    100.0,
                    900.0,
                    sequencer::macro_engine::MacroCurve::Linear,
                )
                .expect("effect mapping"),
            )
            .expect("unique effect owner");
        effect_app.set_macro_value(effect_id, 0.5);
        sync_track_effect_param_value_field(&mut runtime, &effect_app, 0, 0, 0, None);
        let effect_field = track_effect_param_value_field(0, 0, 0, &effect_desc.params[0].name);
        assert_eq!(reactive_number(&runtime, "SEQ", &effect_field), Some(500.0));
        sync_track_effect_param_value_field(&mut runtime, &effect_app, 0, 0, 0, Some(4));
        assert_eq!(
            reactive_number(&runtime, "SEQ", &effect_field),
            Some(500.0),
            "a playing step without a p-lock must display the macro-effective effect value"
        );
        effect_state.pattern.effect_chains[0][0].set_plock(4, 0, 700.0);
        sync_track_effect_param_value_field(&mut runtime, &effect_app, 0, 0, 0, Some(4));
        assert_eq!(
            reactive_number(&runtime, "SEQ", &effect_field),
            Some(700.0),
            "an explicit effect p-lock must remain visible above the macro"
        );
    }

    #[test]
    fn macro_mapping_sidebar_renders_editable_range_curve_and_state_rows() {
        let desc = sequencer::effects::EffectDescriptor::builtin_sampler();
        let mut app = test_app_with_instrument_descriptor(desc.clone());
        let id = app
            .macro_engine
            .ensure_macro("delay-push", "Delay Push")
            .expect("macro");
        app.macro_engine
            .add_mapping(
                id,
                sequencer::macro_engine::MacroMapping::new_resolved(
                    0,
                    sequencer::process::ParamTarget::InstrumentParam {
                        param: desc.params[0].name.clone(),
                        param_id: None,
                    },
                    Some(0),
                    10.0,
                    30.0,
                    sequencer::macro_engine::MacroCurve::Linear,
                )
                .expect("mapping"),
            )
            .expect("unique owner");

        let mut editor = full_grid_editor_for_scroll_tests();
        sync_macro_state(editor.runtime_mut(), &app);
        editor
            .runtime_mut()
            .eval_str(&format!(
                "(do (set! eseq.macro-state/mapping-open true) (set! eseq.macro-state/mapping-selected {id}))"
            ))
            .expect("arm mapping");
        editor.runtime_mut().run_reactive_cycle();
        editor.refresh_runtime_side_effects();
        editor
            .runtime_mut()
            .eval_str(
                r#"(set-layout (list :buf "*macro-mappings*" :hide-status true :min-width 46))"#,
            )
            .expect("isolate mapping sidebar");
        editor.refresh_runtime_side_effects();
        let buffer_id = editor
            .buffers
            .iter()
            .find(|buffer| buffer.name == "*macro-mappings*")
            .expect("mapping sidebar buffer")
            .id;
        editor.set_active_buffer(buffer_id);
        editor.set_layout_viewport(64, 24);
        let layout = editor.widget_layout().expect("mapping sidebar layout");
        assert_finite_layout_tree(&layout);
        let row = find_layout_node_by_debug_name(&layout, "macro-mapping-table-row")
            .unwrap_or_else(|| panic!("mapping table row; layout={layout:#?}"));
        let min = find_layout_node_by_debug_name(&layout, "macro-mapping-min")
            .expect("mapping min picker");
        let max = find_layout_node_by_debug_name(&layout, "macro-mapping-max")
            .expect("mapping max picker");
        let curve = find_layout_node_by_debug_name(&layout, "macro-mapping-curve")
            .expect("mapping curve dropdown");
        let state = find_layout_node_by_debug_name(&layout, "macro-mapping-state")
            .expect("mapping state label");
        let unmap = find_layout_node_by_debug_name(&layout, "macro-mapping-unmap")
            .expect("mapping unmap button");
        for (node, label) in [
            (row, "row"),
            (min, "min"),
            (max, "max"),
            (curve, "curve"),
            (state, "state"),
            (unmap, "unmap"),
        ] {
            assert_finite_nonzero_rect(node, label);
        }
        assert_eq!(layout_prop_number(min, "value"), Some(10.0));
        assert_eq!(layout_prop_number(max, "value"), Some(30.0));
        assert!(matches!(
            curve.props.get("value"),
            Some(Value::String(value)) if value == "linear"
        ));
        assert!(matches!(
            state.props.get("text"),
            Some(Value::String(value)) if value == "live"
        ));
        editor.drain_host_commands();
        editor
            .runtime_mut()
            .invoke(
                min.props.get("on-change").cloned().expect("min callback"),
                vec![Value::Number(12.5)],
            )
            .expect("edit mapping min");
        assert!(matches!(
            editor.drain_host_commands().as_slice(),
            [eseqlisp::host::HostCommand::Custom { name, payload: Value::Map(payload) }]
                if name == "macro-set-range"
                    && matches!(payload.get("min").map(|value| value.borrow().clone()), Some(Value::Number(value)) if (value - 12.5).abs() < 1.0e-6)
        ));
        editor
            .runtime_mut()
            .invoke(
                curve
                    .props
                    .get("on-change")
                    .cloned()
                    .expect("curve callback"),
                vec![Value::String("log".to_string())],
            )
            .expect("edit mapping curve");
        assert!(matches!(
            editor.drain_host_commands().as_slice(),
            [eseqlisp::host::HostCommand::Custom { name, payload: Value::Map(payload) }]
                if name == "macro-set-curve"
                    && matches!(payload.get("curve").map(|value| value.borrow().clone()), Some(Value::String(value)) if value == "log")
        ));
    }

