    #[test]
    fn metal_seq_script_picker_lists_lisp_scripts() {
        let mut editor = full_grid_editor_for_scroll_tests();

        let root_value = editor
            .runtime_mut()
            .eval_str(
                r#"
                (map
                  (lambda (entry) (get entry :name))
                  (filter
                    (lambda (entry) (eseq.seq-script-picker/seq-script-entry-visible? entry))
                    (list-directory seq-script-picker-current-dir)))
                "#,
            )
            .expect("list script picker entries")
            .expect("script picker entries value");
        let Value::List(root_items) = root_value else {
            panic!("expected script picker entries to be a list");
        };
        let root_text = root_items
            .iter()
            .map(|item| match &*item.borrow() {
                Value::String(name) => name.clone(),
                other => panic!("expected script name string, got {other:?}"),
            })
            .collect::<Vec<_>>()
            .join("\n");
        assert!(
            root_text.contains("processes")
                && root_text.contains("sequencers")
                && root_text.contains("ui"),
            "script picker should expose the organized script groups; entries:\n{root_text}"
        );
        assert!(
            !root_text.contains("generate_dgenlisp_api.py"),
            "script picker should filter non-lisp files; entries:\n{root_text}"
        );

        let value = editor
            .runtime_mut()
            .eval_str(
                r#"
                (do
                  (set! seq-script-picker-current-dir
                    (path-join (eseq.seq-script-picker/seq-script-default-dir) "sequencers"))
                  (map
                    (lambda (entry) (get entry :name))
                    (filter
                      (lambda (entry) (eseq.seq-script-picker/seq-script-entry-visible? entry))
                      (list-directory seq-script-picker-current-dir))))
                "#,
            )
            .expect("list organized sequencer script entries")
            .expect("sequencer script entries value");
        let Value::List(items) = value else {
            panic!("expected sequencer script entries to be a list");
        };
        let text = items
            .iter()
            .map(|item| match &*item.borrow() {
                Value::String(name) => name.clone(),
                other => panic!("expected script name string, got {other:?}"),
            })
            .collect::<Vec<_>>()
            .join("\n");
        assert!(
            text.contains("graph-neural-8x8-demo.lisp"),
            "script picker should list lisp scripts; entries:\n{text}"
        );
        assert!(
            text.contains("graph-neural-16-demo.lisp"),
            "script picker should include graph demos; entries:\n{text}"
        );
        let scratch_entry = editor
            .runtime_mut()
            .eval_str(
                r#"(eseq.seq-script-picker/seq-script-scratch-entry "scripts/sequencers/graph-neural-8x8-demo.lisp")"#,
            )
            .expect("build script scratch entry")
            .expect("script scratch entry value");
        let Value::List(lines) = scratch_entry else {
            panic!("expected script scratch entry to be a list");
        };
        let lines = lines
            .iter()
            .map(|line| match &*line.borrow() {
                Value::String(line) => line.clone(),
                other => panic!("expected scratch entry line string, got {other:?}"),
            })
            .collect::<Vec<_>>();
        assert_eq!(
            lines,
            vec!["(load \"crates/sequencer/scripts/sequencers/graph-neural-8x8-demo.lisp\")"],
            "scratch entry should persist only the project-relative load form"
        );
    }

    #[test]
