    #[test]
    fn metal_seq_16_cycle_script_effect_buffer_matches_script_contract() {
        let src = std::fs::read_to_string("scripts/sequencers/graph-neural-16-cycle-demo.lisp")
            .expect("read 16-cycle script");
        let tokens = Parser::new(src).parse().expect("tokenize 16-cycle script");
        let exprs = ASTParser::new(tokens)
            .parse()
            .expect("parse 16-cycle script");

        let mut script_buffer_name = None;
        let mut effect_buffer_targets = Vec::new();
        for expr in &exprs {
            let Expression::List(items) = expr else {
                continue;
            };
            match items.as_slice() {
                [
                    Expression::Symbol(form),
                    Expression::Symbol(name),
                    Expression::String(value),
                    ..,
                ] if form == "def" && name == "script-buffer-name" => {
                    script_buffer_name = Some(value.clone());
                }
                [Expression::Symbol(form), Expression::String(target), ..]
                    if form == "effect-buffer" =>
                {
                    effect_buffer_targets.push(target.clone());
                }
                [Expression::Symbol(form), Expression::Symbol(target), ..]
                    if form == "effect-buffer" =>
                {
                    panic!(
                        "effect-buffer target names are literal; pass a string target, not symbol {target}"
                    );
                }
                _ => {}
            }
        }

        let script_buffer_name =
            script_buffer_name.expect("script should define script-buffer-name");
        assert_eq!(
            effect_buffer_targets,
            vec![script_buffer_name],
            "16-cycle script tab registration and effect-buffer must target the same buffer"
        );
    }

    #[test]
    fn metal_seq_macro_player_script_renders_visible_controls_in_its_own_tab() {
        let mut editor = full_grid_editor_for_scroll_tests();
        editor.drain_host_commands();
        let src = std::fs::read_to_string("scripts/ui/macro-player-demo.lisp")
            .expect("read macro player demo");
        editor
            .runtime_mut()
            .eval_source_at_path(PathBuf::from("scripts/ui/macro-player-demo.lisp"), &src)
            .expect("evaluate macro player demo");

        let commands = editor.drain_host_commands();
        assert_eq!(
            commands.len(),
            3,
            "each declaration should ensure one macro"
        );
        let mut app = test_app_with_instrument_descriptor(
            sequencer::effects::EffectDescriptor::builtin_sampler(),
        );
        for command in commands {
            let eseqlisp::host::HostCommand::Custom { name, payload } = command else {
                panic!("macro declaration should emit a custom host command");
            };
            assert_eq!(name, "macro-ensure");
            let Value::Map(payload) = payload else {
                panic!("macro-ensure payload should be a map");
            };
            let Value::String(key) = payload["key"].borrow().clone() else {
                panic!("macro-ensure key should be a string");
            };
            let Value::String(name) = payload["name"].borrow().clone() else {
                panic!("macro-ensure name should be a string");
            };
            app::apply_command(&mut app, app::AppCommand::MacroEnsure { key, name });
        }
        sync_macro_state(editor.runtime_mut(), &app);
        editor.runtime_mut().run_reactive_cycle();
        editor.refresh_runtime_side_effects();
        editor
            .runtime_mut()
            .eval_str(
                r#"(set-layout (list :buf "*macro-player*" :hide-status true :min-width 25))"#,
            )
            .expect("isolate macro player buffer");
        editor.refresh_runtime_side_effects();
        if let Some(status) = editor.runtime_mut().take_status_message() {
            panic!("macro player demo status after refresh: {status}");
        }

        let buffer_id = editor
            .buffers
            .iter()
            .find(|buffer| buffer.name == "*macro-player*")
            .expect("macro player effect buffer")
            .id;
        editor.set_active_buffer(buffer_id);
        editor.set_layout_viewport(80, 24);
        let layout = editor.widget_layout().unwrap_or_else(|| {
            let tree = editor
                .buffers
                .iter()
                .find(|buffer| buffer.id == buffer_id)
                .and_then(|buffer| buffer.widget_tree.as_ref());
            panic!("macro player layout; widget tree={tree:#?}")
        });
        assert_finite_layout_tree(&layout);
        let title = find_layout_node_by_stable_key(&layout, "macro-player-title")
            .expect("macro player title");
        let mapping_editor = find_layout_node_by_debug_name(&layout, "macro-mapping-editor")
            .expect("embedded macro mapping editor");
        let mapping_empty = find_layout_node_by_debug_name(&layout, "macro-mapping-editor-empty")
            .expect("empty mapping editor state");
        assert_finite_nonzero_rect(&layout, "macro player surface");
        assert_finite_nonzero_rect(title, "macro player title");
        assert_finite_nonzero_rect(mapping_editor, "macro player mapping editor");
        assert_finite_nonzero_rect(mapping_empty, "macro player empty mapping state");

        let mut knob_count = 0;
        let mut button_count = 0;
        let mut momentary_count = 0;
        let mut map_button_count = 0;
        fn count_controls(
            node: &eseqlisp::layout::LayoutNode,
            knob_count: &mut usize,
            button_count: &mut usize,
            momentary_count: &mut usize,
            map_button_count: &mut usize,
        ) {
            if node.widget_type == "knob-number" {
                *knob_count += 1;
                assert_finite_nonzero_rect(node, "macro player knob");
            } else if node.widget_type == "button" {
                *button_count += 1;
                assert_finite_nonzero_rect(node, "macro player button");
                match node.props.get("debug-name") {
                    Some(Value::String(name)) if name == "macro-momentary" => {
                        *momentary_count += 1;
                    }
                    Some(Value::String(name)) if name == "macro-map-button" => {
                        *map_button_count += 1;
                    }
                    _ => {}
                }
            }
            for child in &node.children {
                count_controls(
                    child,
                    knob_count,
                    button_count,
                    momentary_count,
                    map_button_count,
                );
            }
        }
        count_controls(
            &layout,
            &mut knob_count,
            &mut button_count,
            &mut momentary_count,
            &mut map_button_count,
        );
        assert_eq!(knob_count, 3);
        assert_eq!(button_count, 6);
        assert_eq!(momentary_count, 3);
        assert_eq!(map_button_count, 3);
        assert_eq!(
            editor
                .runtime_mut()
                .eval_str("(get (eseq.macros/macro-by-key :delay-push) :name)"),
            Ok(Some(Value::String("Delay Push".to_string()))),
            "engine readback should replace the fallback key label"
        );
        assert_eq!(
            editor
                .runtime_mut()
                .eval_str("(eseq.macros/macro-toggle-mapping-arm :delay-push)"),
            Ok(Some(Value::Bool(true))),
            "the resolved player control should enter macro map mode"
        );
        editor.refresh_runtime_side_effects();
        assert!(
            editor_has_visible_buffer(&editor, "*macro-mappings*"),
            "mapping mode should replace the normal browser sidebar with the mapping table"
        );
        assert_eq!(
            editor.runtime_mut().eval_str(
                r#"(len (filter |tab| (and (= (nth tab 0) "Player") (= (nth tab 1) "*macro-player*")) eseq.seq-step-tabs/seq-registered-step-tabs))"#,
            ),
            Ok(Some(Value::Number(1.0))),
            "player surface should register as a script-owned tab",
        );
    }

    #[test]
    fn metal_seq_piano_roll_shortcuts_are_lower_panel_only() {
        let mut editor = full_grid_editor_for_scroll_tests();

        assert_eq!(
            editor
                .runtime_mut()
                .eval_str("eseq.seq-step-tabs/piano-roll-placement")
                .unwrap(),
            Some(Value::Keyword("bottom".to_string()))
        );
        assert_eq!(
            editor.runtime_mut().eval_str("eseq.seq-step-tabs/step-panel-buffer").unwrap(),
            Some(Value::String("*sequencer*".to_string()))
        );
        assert_eq!(
            editor.runtime_mut().eval_str("eseq.seq-step-tabs/lower-panel-buffer").unwrap(),
            Some(Value::String("*fx*".to_string()))
        );

        editor
            .runtime_mut()
            .eval_str("(eseq.seq-panels/seq-toggle-piano-roll-placement)")
            .expect("placement toggle should be bottom-only");
        assert_eq!(
            editor
                .runtime_mut()
                .eval_str("eseq.seq-step-tabs/piano-roll-placement")
                .unwrap(),
            Some(Value::Keyword("bottom".to_string()))
        );
        assert_eq!(
            editor.runtime_mut().eval_str("eseq.seq-step-tabs/step-panel-buffer").unwrap(),
            Some(Value::String("*sequencer*".to_string())),
            "placement toggle while closed must not open or move piano roll"
        );
        assert_eq!(
            editor.runtime_mut().eval_str("eseq.seq-step-tabs/lower-panel-buffer").unwrap(),
            Some(Value::String("*fx*".to_string())),
            "placement toggle while closed should leave the FX lower pane visible"
        );

        editor
            .runtime_mut()
            .eval_str("(eseq.seq-panels/seq-toggle-main-or-piano-roll)")
            .expect("open piano roll in lower panel");
        assert_eq!(
            editor.runtime_mut().eval_str("eseq.seq-step-tabs/step-panel-buffer").unwrap(),
            Some(Value::String("*sequencer*".to_string()))
        );
        assert_eq!(
            editor.runtime_mut().eval_str("eseq.seq-step-tabs/lower-panel-buffer").unwrap(),
            Some(Value::String("*piano-roll*".to_string()))
        );

        editor
            .runtime_mut()
            .eval_str("(eseq.seq-panels/seq-toggle-piano-roll-placement)")
            .expect("placement toggle while open should keep lower placement");
        assert_eq!(
            editor
                .runtime_mut()
                .eval_str("eseq.seq-step-tabs/piano-roll-placement")
                .unwrap(),
            Some(Value::Keyword("bottom".to_string()))
        );
        assert_eq!(
            editor.runtime_mut().eval_str("eseq.seq-step-tabs/step-panel-buffer").unwrap(),
            Some(Value::String("*sequencer*".to_string()))
        );
        assert_eq!(
            editor.runtime_mut().eval_str("eseq.seq-step-tabs/lower-panel-buffer").unwrap(),
            Some(Value::String("*piano-roll*".to_string()))
        );

        editor
            .runtime_mut()
            .eval_str("(eseq.seq-panels/seq-toggle-main-or-piano-roll)")
            .expect("close lower piano roll");
        assert_eq!(
            editor.runtime_mut().eval_str("eseq.seq-step-tabs/step-panel-buffer").unwrap(),
            Some(Value::String("*sequencer*".to_string()))
        );
        assert_eq!(
            editor.runtime_mut().eval_str("eseq.seq-step-tabs/lower-panel-buffer").unwrap(),
            Some(Value::String("*fx*".to_string()))
        );
    }

    #[test]
    fn metal_seq_bottom_piano_roll_layout_preserves_main_sequencer_panel() {
        let mut editor = full_grid_editor_for_scroll_tests();

        editor
            .runtime_mut()
            .eval_str("(eseq.seq-panels/seq-toggle-main-or-piano-roll)")
            .expect("open piano roll in bottom panel");
        editor.refresh_runtime_side_effects();

        let tile_buffers = collect_tile_buffer_names(&editor);
        assert!(
            tile_buffers.contains(&"*sequencer*".to_string()),
            "bottom piano roll layout should keep the sequencer panel visible: {tile_buffers:?}"
        );
        assert!(
            tile_buffers.contains(&"*step*".to_string()),
            "bottom piano roll layout should keep the step context panel visible: {tile_buffers:?}"
        );
        assert!(
            tile_buffers.contains(&"*track*".to_string()),
            "bottom piano roll layout should keep the track parameters panel visible: {tile_buffers:?}"
        );
        assert!(
            tile_buffers.contains(&"*piano-roll*".to_string()),
            "bottom piano roll layout should replace the FX lower pane with piano roll: {tile_buffers:?}"
        );
        assert!(
            !tile_buffers.contains(&"*fx*".to_string()),
            "bottom piano roll layout should not keep the FX buffer in the lower pane: {tile_buffers:?}"
        );

        let track_count = tile_buffers
            .iter()
            .filter(|name| name.as_str() == "*track*")
            .count();
        assert_eq!(
            track_count, 1,
            "bottom piano roll layout should have one expanded track tile: {tile_buffers:?}"
        );
    }

