    #[test]
    fn editor_macro_action_recomputes_only_when_its_inputs_change() {
        use crate::edit_sessions::{
            active_instrument_editor_macro_action, editor_macro_action_fingerprint,
            editor_macro_action_strings,
        };
        use eseqlisp::widget_render::patcher::open_macro_view_for_path_for_test;

        let path = std::env::temp_dir().join(format!(
            "eseq-editor-macro-action-{}/dsp.lisp",
            std::process::id()
        ));
        let mut sessions = crate::loop_ctx::EditSessionState::default();
        sessions.instrument_edit_session = Some(
            crate::edit_sessions::InstrumentEditSession::begin_edit_existing(
                "probe".to_string(),
                path.clone(),
                "*probe*".to_string(),
                0,
                0,
                "(defmacro shape (x) (* x 2))\n(def input (in 1))\n(out (shape input) 1)"
                    .to_string(),
                sequencer::sequencer::CustomInstrumentRunMode::Instrument,
                crate::edit_sessions::EditorSurface::Patch,
            ),
        );

        // Root view: no macro is active, so there is no button state, and the
        // fingerprint is stable across ticks.
        let root_fingerprint = editor_macro_action_fingerprint(&sessions);
        assert_eq!(root_fingerprint, editor_macro_action_fingerprint(&sessions));
        let session = sessions.instrument_edit_session.as_ref().unwrap();
        assert_eq!(
            editor_macro_action_strings(active_instrument_editor_macro_action(session).as_ref()),
            (String::new(), String::new())
        );

        // Opening the local macro's view changes the fingerprint and offers
        // save-to-library.
        open_macro_view_for_path_for_test(&path, Some("shape"));
        let macro_fingerprint = editor_macro_action_fingerprint(&sessions);
        assert_ne!(macro_fingerprint, root_fingerprint);
        assert_eq!(macro_fingerprint, editor_macro_action_fingerprint(&sessions));
        let session = sessions.instrument_edit_session.as_ref().unwrap();
        assert_eq!(
            editor_macro_action_strings(active_instrument_editor_macro_action(session).as_ref()),
            ("shape".to_string(), "save-to-library".to_string())
        );

        // Editing the source re-fingerprints; with the local defmacro gone the
        // button state drops back to nothing.
        let session = sessions.instrument_edit_session.as_mut().unwrap();
        session.last_valid_source = "(def input (in 1))\n(out input 1)".to_string();
        let edited_fingerprint = editor_macro_action_fingerprint(&sessions);
        assert_ne!(edited_fingerprint, macro_fingerprint);
        let session = sessions.instrument_edit_session.as_ref().unwrap();
        assert_eq!(
            editor_macro_action_strings(active_instrument_editor_macro_action(session).as_ref()),
            (String::new(), String::new())
        );

        open_macro_view_for_path_for_test(&path, None);
    }

    #[test]
    fn scan_patch_macro_source_collects_calls_and_imports() {
        let scan = crate::edit_sessions::scan_patch_macro_source(
            "(use-defmacro dcblock)\n\
             (defmacro comb (x) (dcblock (* x 0.5)))\n\
             (defmacro reverb (in) (+ (comb in) (comb (* in 2))))\n\
             (def input (in 1))\n\
             (out (reverb input) 1)",
        );
        assert_eq!(scan.imports, vec!["dcblock".to_string()]);
        let names: Vec<&str> = scan
            .locals
            .iter()
            .map(|(name, _, _)| name.as_str())
            .collect();
        assert_eq!(names, vec!["comb", "reverb"]);
        let comb_calls = &scan.locals[0].2;
        assert!(
            comb_calls.contains(&"dcblock".to_string()),
            "comb should record its dcblock call: {comb_calls:?}"
        );
        let reverb_calls = &scan.locals[1].2;
        assert!(
            reverb_calls.contains(&"comb".to_string()),
            "reverb should record its comb call (deduped): {reverb_calls:?}"
        );
        assert_eq!(
            reverb_calls.iter().filter(|call| *call == "comb").count(),
            1,
            "calls should be deduped"
        );
    }

    #[test]
    fn metal_seq_patch_macros_sidebar_nests_call_structure() {
        let mut editor = full_grid_editor_for_scroll_tests();
        editor
            .runtime_mut()
            .eval_str(
                r#"(reactive-set "SEQ" "editor-patch-macros"
                     (list (dict :name "reverb" :params (list "in") :calls (list "comb"))
                           (dict :name "comb" :params (list "x") :calls (list "dcblock"))))"#,
            )
            .expect("set patch macros");
        editor
            .runtime_mut()
            .eval_str(
                r#"(reactive-set "SEQ" "editor-library-macros"
                     (list (dict :name "dcblock" :params (list "x") :calls (list) :used true)))"#,
            )
            .expect("set library macros");

        // In Patch shows only the root (reverb); comb is nested beneath it,
        // and the library macro dcblock nests beneath comb.
        assert_eq!(
            editor
                .runtime_mut()
                .eval_str("(get (nth (eseq.patch-macros/patch-macros-items) 1) :name)")
                .unwrap(),
            Some(Value::String("reverb".to_string())),
            "reverb should be the only In Patch root"
        );
        assert_eq!(
            editor
                .runtime_mut()
                .eval_str("(get (nth (get (nth (eseq.patch-macros/patch-macros-items) 1) :children) 0) :name)")
                .unwrap(),
            Some(Value::String("comb".to_string())),
        );
        assert_eq!(
            editor
                .runtime_mut()
                .eval_str(
                    "(get (nth (get (nth (get (nth (eseq.patch-macros/patch-macros-items) 1) :children) 0) :children) 0) :name)"
                )
                .unwrap(),
            Some(Value::String("dcblock".to_string())),
        );
        // Used library macros get the distinct icon.
        assert_eq!(
            editor
                .runtime_mut()
                .eval_str("(get (nth (eseq.patch-macros/patch-macros-items) 3) :icon)")
                .unwrap(),
            Some(Value::Keyword("sliders".to_string())),
            "library section row for a used macro should use the :sliders icon"
        );
    }

