    /// Sound palette fixture (takes spec 17.6): two entries — the gray base
    /// (scene-effective, color nil) and a colored current entry.
    fn sound_palette_fixture() -> Value {
        map_value([
            ("track", Value::Number(0.0)),
            ("target-kind", Value::String("take".to_string())),
            ("target-id", Value::Number(1.0)),
            (
                "instrument-name",
                Value::String("ultrakick".to_string()),
            ),
            (
                "entries",
                test_list(vec![
                    map_value([
                        ("patch-id", Value::Number(0.0)),
                        ("mix-id", Value::Number(0.0)),
                        ("name", Value::String("Patch 1".to_string())),
                        ("referents", Value::String("Scene 1".to_string())),
                        ("base", Value::Bool(true)),
                        ("current", Value::Bool(false)),
                        ("color", Value::Nil),
                        ("preset", Value::Nil),
                        ("sample", Value::Nil),
                        ("diff-up", Value::Number(3.0)),
                        ("diff-down", Value::Number(1.0)),
                    ]),
                    map_value([
                        ("patch-id", Value::Number(3.0)),
                        ("mix-id", Value::Number(2.0)),
                        ("name", Value::String("Warm Keys".to_string())),
                        ("referents", Value::String("Pattern 3, Take 2".to_string())),
                        ("base", Value::Bool(false)),
                        ("current", Value::Bool(true)),
                        // This pair IS the track's own sound (track-sound
                        // spec §2.1): the card renders the TRK chip.
                        ("track-sound", Value::Bool(true)),
                        ("color", Value::Number(1.0)),
                        ("color-r", Value::Number(0.909_803_9)),
                        ("color-g", Value::Number(0.643_137_3)),
                        ("color-b", Value::Number(0.309_803_93)),
                        (
                            "glyph-key",
                            Value::String("sound-glyph:track:0:patch:3".to_string()),
                        ),
                        ("preset", Value::String("Warm Keys.json".to_string())),
                        ("sample", Value::Nil),
                        ("diff-up", Value::Number(0.0)),
                        ("diff-down", Value::Number(0.0)),
                    ]),
                ]),
            ),
        ])
    }

    /// eseq-chk: since S4 retired the flat compat aliases, `C-x p` binds the
    /// QUALIFIED handler string `eseq.sound-palette/toggle-open` — a flat
    /// spelling that is not a def's base name dispatches to nothing. Prove
    /// the chord reaches the palette-open native end to end, and pin the
    /// defs the other requalified binding names (`C-h` collapse-all).
    #[test]
    fn metal_seq_cx_p_chord_opens_the_sound_palette() {
        use crossterm::event::{KeyCode, KeyEvent, KeyModifiers};
        let mut editor = full_grid_editor_for_scroll_tests();
        // The fixture loads the UI but never syncs runtime `bind-key`
        // registrations into the editor's dispatch table; a real session
        // does this every frame.
        editor.refresh_runtime_side_effects();
        // The fixture's palette natives are silent `true` stubs; make the
        // open native observable so the assertion sees the dispatch.
        editor
            .runtime_mut()
            .register_native("seq-sound-palette-open", |_args, ctx| {
                ctx.enqueue_command(eseqlisp::host::HostCommand::Custom {
                    name: "palette-open-probe".to_string(),
                    payload: Value::Nil,
                });
                Ok(Value::Bool(true))
            });
        editor.drain_host_commands();
        editor.handle_key(KeyEvent::new(KeyCode::Char('x'), KeyModifiers::CONTROL));
        editor.handle_key(KeyEvent::new(KeyCode::Char('p'), KeyModifiers::NONE));
        let commands = editor.drain_host_commands();
        assert!(
            commands.iter().any(|command| matches!(
                command,
                eseqlisp::host::HostCommand::Custom { name, .. } if name == "palette-open-probe"
            )),
            "C-x p should reach the seq-sound-palette-open native, got {commands:?}"
        );
        assert!(
            editor
                .runtime()
                .has_global("eseq.sequencer/collapse-all-tracks"),
            "the C-h mode binding names this def; renaming it orphans the key"
        );
    }

    /// Takes spec 18.3 exit criterion: the palette overlay renders — header,
    /// both entry rows (gray base + colored current), the preset/sample
    /// source line, and the param diff badges — all inside the panel;
    /// closed (Nil) it collapses. Apply is the row click itself.
    #[test]
    fn metal_seq_sound_palette_overlay_layout() {
        let mut editor = full_grid_editor_for_scroll_tests();
        editor
            .runtime_mut()
            .set_reactive("SEQ", "sound-palette", sound_palette_fixture());
        editor
            .runtime_mut()
            .eval_str(r#"(effect-buffer "*sound-palette-test*" (eseq.sound-palette/panel))"#)
            .expect("create sound palette test buffer");
        editor.refresh_runtime_side_effects();
        let buffer_id = editor
            .buffers
            .iter()
            .find(|buffer| buffer.name == "*sound-palette-test*")
            .expect("sound palette test buffer")
            .id;
        editor.set_active_buffer(buffer_id);
        editor.set_layout_viewport(24, 60);
        editor.refresh_visible_layouts_for_buffer_named("*sound-palette-test*");
        let layout = editor.widget_layout().expect("sound palette layout");
        let panel = find_layout_node_by_debug_name(&layout, "sound-palette-panel")
            .expect("palette panel should render");
        let header = find_layout_node_by_stable_key_suffix(&layout, "/header-label")
            .expect("palette header should render");
        let base_row = find_layout_node_by_stable_key_suffix(&layout, "/entry-0")
            .expect("gray base entry should render");
        let current_row = find_layout_node_by_stable_key_suffix(&layout, "/entry-3")
            .expect("current entry should render");
        let source = find_layout_node_by_stable_key_suffix(&layout, "/source-3")
            .expect("preset/sample source label should render");
        let diff_up = find_layout_node_by_stable_key_suffix(&layout, "/diff-up-0")
            .expect("diff badge should render");
        assert_finite_nonzero_rect(panel, "sound palette panel");
        assert_finite_nonzero_rect(base_row, "gray base entry");
        assert_finite_nonzero_rect(current_row, "current entry");
        assert_layout_inside(header, panel, "palette header");
        assert_layout_inside(base_row, panel, "gray base entry");
        assert_layout_inside(current_row, panel, "current entry");
        // Track-sound marker (track-sound spec §2.1): the entry flagged
        // :track-sound renders the TRK chip inside its card; unflagged
        // entries render none. (Asserted before the source-label containment
        // check below, which is a known pre-existing card-height overflow.)
        let trk_chip = find_layout_node_by_stable_key_suffix(&layout, "/trk-3")
            .expect("the track-sound entry renders its TRK chip");
        assert_finite_nonzero_rect(trk_chip, "TRK chip");
        assert_layout_inside(trk_chip, current_row, "TRK chip");
        assert!(
            find_layout_node_by_stable_key_suffix(&layout, "/trk-0").is_none(),
            "an entry that is not the track sound renders no TRK chip"
        );
        assert_layout_inside(source, current_row, "preset/sample source label");
        assert_layout_inside(diff_up, base_row, "diff badge");

        // Sound-glyph spec P2: each box carries the plant glyph as its
        // center region, fed by the host-published frame key.
        let glyph = find_layout_node_by_stable_key_suffix(&layout, "/glyph-3")
            .expect("sound glyph widget should render");
        assert_eq!(glyph.widget_type, "sound-glyph");
        assert_finite_nonzero_rect(glyph, "sound glyph");
        assert_layout_inside(glyph, current_row, "sound glyph");
        assert_eq!(
            glyph.props.get("source").map(|value| value.clone()),
            Some(Value::String("sound-glyph:track:0:patch:3".to_string())),
            "glyph source key comes from the entry's glyph-key"
        );

        // Closed again: the reactive Nil collapses the panel to nothing.
        editor
            .runtime_mut()
            .set_reactive("SEQ", "sound-palette", Value::Nil);
        editor.runtime_mut().run_reactive_cycle();
        editor.refresh_runtime_side_effects();
        editor.refresh_visible_layouts_for_buffer_named("*sound-palette-test*");
        let layout = editor.widget_layout().expect("closed palette layout");
        assert!(
            find_layout_node_by_stable_key_suffix(&layout, "/entry-3").is_none(),
            "a closed palette renders no entries"
        );
    }

    /// Inspect mode over the open sound palette (real tiled UI): every
    /// hover hit must land inside the modal subtree — never on the widgets
    /// behind the panel — and hovering the panel must hit something.
    #[cfg(target_os = "macos")]
    #[test]
    fn metal_seq_inspect_mode_hits_sound_palette_modal_not_behind_it() {
        fn find_modal<'a>(
            node: &'a eseqlisp::layout::LayoutNode,
        ) -> Option<&'a eseqlisp::layout::LayoutNode> {
            if node.widget_type == "modal" && !node.children.is_empty() {
                return Some(node);
            }
            node.children.iter().find_map(find_modal)
        }

        let mut editor = full_grid_editor_for_scroll_tests();
        assert!(
            editor.switch_active_tile_to_buffer_named("*step*"),
            "step tile must exist in the startup grid"
        );
        editor
            .runtime_mut()
            .set_reactive("SEQ", "sound-palette", sound_palette_fixture());
        editor.runtime_mut().run_reactive_cycle();
        editor.refresh_runtime_side_effects();
        let _ = eseqlisp::frame::build_tiled_render_frame_borderless(&mut editor, 140, 36);

        let layout = editor.widget_layout().expect("step layout");
        let modal = find_modal(&layout).expect("open sound palette modal").clone();

        // Register the overlay entry exactly as a live frame draw would.
        let _ = eseqlisp::widget_render::collect_metal_primitives(
            &layout,
            eseqlisp::widget_render::WidgetViewport {
                cell_w: 10.0,
                cell_h: 20.0,
                vp_w: 1400.0,
                vp_h: 720.0,
                time_seconds: 0.0,
                focused_widget_id: None,
                focused_branch: false,
                overlay_viewport_bottom: 36.0,
                scroll_top: 0.0,
                scroll_left: 0.0,
                inherited_hover: false,
            },
            0.0,
            36,
        );
        assert!(
            eseqlisp::widget_render::topmost_overlay().is_some(),
            "the open palette must register a modal overlay entry"
        );

        editor.toggle_inspect_mode();
        let mut hits_inside = 0usize;
        let mut hits_outside = Vec::new();
        for row_step in 0..18 {
            for col_step in 0..35 {
                let precise_col = col_step as f32 * 4.0 + 2.0;
                let precise_row = row_step as f32 * 2.0 + 1.0;
                editor.handle_tiled_mouse_precise(
                    crossterm::event::MouseEvent {
                        kind: crossterm::event::MouseEventKind::Moved,
                        column: precise_col as u16,
                        row: precise_row as u16,
                        modifiers: crossterm::event::KeyModifiers::NONE,
                    },
                    precise_col,
                    precise_row,
                    0,
                );
                let Some(hover_id) = editor.inspect_hovered_widget_id() else {
                    continue;
                };
                if eseqlisp::layout::layout_contains_widget_id(&modal, hover_id) {
                    hits_inside += 1;
                } else {
                    hits_outside.push((precise_col, precise_row, hover_id));
                }
            }
        }
        eseqlisp::widget_render::clear_overlay();
        assert!(
            hits_outside.is_empty(),
            "inspect hover must never select widgets behind the open palette: {hits_outside:?}"
        );
        assert!(
            hits_inside > 0,
            "inspect hover over the panel must select palette widgets"
        );
    }

    /// The overlay's Apply/Apply-with-mix rows dispatch the palette natives
    /// with the entry's ids (takes spec 17.6).
    #[test]
    fn metal_seq_sound_palette_apply_click_dispatches_the_entry() {
        let mut editor = full_grid_editor_for_scroll_tests();
        editor
            .runtime_mut()
            .set_reactive("SEQ", "sound-palette", sound_palette_fixture());
        editor.runtime_mut().run_reactive_cycle();
        // Capture the native calls as host commands so the dispatch is
        // observable (the real natives enqueue the same wire commands).
        editor
            .runtime_mut()
            .register_native("seq-sound-apply", |args, ctx| {
                ctx.enqueue_command(eseqlisp::host::HostCommand::Custom {
                    name: "test-sound-apply".to_string(),
                    payload: Value::List(
                        args.iter()
                            .map(|value| std::rc::Rc::new(std::cell::RefCell::new(value.clone())))
                            .collect(),
                    ),
                });
                Ok(Value::Bool(true))
            });
        editor.drain_host_commands();
        editor
            .runtime_mut()
            .eval_str(r#"(eseq.sound-palette/apply-entry (dict :patch-id 3 :mix-id 2))"#)
            .expect("apply the fixture entry");
        let commands = editor.drain_host_commands();
        assert_eq!(commands.len(), 1, "commands={commands:?}");
        match &commands[0] {
            eseqlisp::host::HostCommand::Custom { name, payload } => {
                assert_eq!(name, "test-sound-apply");
                let Value::List(args) = payload else {
                    panic!("captured args should be a list: {payload:?}");
                };
                assert_eq!(*args[0].borrow(), Value::Number(0.0), "track from the open palette");
                assert_eq!(*args[1].borrow(), Value::Number(3.0), "the entry's patch id");
            }
            other => panic!("expected the captured apply, got {other:?}"),
        }
    }

    /// Clip dot join logic (takes spec 17.6, amended to patch IDENTITY):
    /// dotted clips yield their patch color, name-only patches the gray
    /// fallback (true), clips with no resolvable sound nothing.
    #[test]
    fn metal_seq_arrangement_clip_sound_dot_resolves_color_and_fallback() {
        let mut editor = full_grid_editor_for_scroll_tests();
        editor.runtime_mut().set_reactive(
            "SEQ",
            "song-clip-sounds",
            test_list(vec![test_list(vec![
                map_value([
                    ("clip-id", Value::Number(5.0)),
                    ("dot", Value::Bool(true)),
                    ("color", Value::Number(1.0)),
                    ("color-r", Value::Number(0.9)),
                    ("color-g", Value::Number(0.6)),
                    ("color-b", Value::Number(0.3)),
                ]),
                map_value([
                    ("clip-id", Value::Number(6.0)),
                    ("dot", Value::Bool(true)),
                    ("color", Value::Nil),
                ]),
                // dot false = the clip's sound does not resolve; the
                // producer never emits color fields alongside it.
                map_value([
                    ("clip-id", Value::Number(7.0)),
                    ("dot", Value::Bool(false)),
                ]),
            ])]),
        );
        editor.runtime_mut().run_reactive_cycle();
        let colored = editor
            .runtime_mut()
            .eval_str("(eseq.arrangement/clip-sound-dot 0 5)")
            .expect("colored clip")
            .expect("dot value");
        let Value::List(rgb) = colored else {
            panic!("expected (r g b), got {colored:?}");
        };
        assert_eq!(*rgb[0].borrow(), Value::Number(0.9));
        assert_eq!(*rgb[2].borrow(), Value::Number(0.3));
        assert_eq!(
            editor
                .runtime_mut()
                .eval_str("(eseq.arrangement/clip-sound-dot 0 6)")
                .expect("name-only clip"),
            Some(Value::Bool(true)),
            "name-only clip uses the gray fallback"
        );
        assert_eq!(
            editor
                .runtime_mut()
                .eval_str("(eseq.arrangement/clip-sound-dot 0 7)")
                .expect("unresolvable clip"),
            Some(Value::Nil),
            "a clip with no resolvable sound draws no dot"
        );
        assert_eq!(
            editor
                .runtime_mut()
                .eval_str("(eseq.arrangement/clip-sound-dot 3 5)")
                .expect("out-of-range track"),
            Some(Value::Nil)
        );
    }

