    #[test]
    fn metal_seq_transport_master_record_button_has_visible_rect() {
        let mut editor = full_grid_editor_for_scroll_tests();
        editor
            .runtime_mut()
            .eval_str(r#"(set-window-buffer "*transport*")"#)
            .expect("switch to transport buffer");
        editor.refresh_runtime_side_effects();

        let layout = editor.widget_layout().expect("transport layout");
        let button = find_layout_node_by_stable_key(&layout, "transport-master-record-button")
            .expect("master recording button");
        assert_finite_nonzero_rect(button, "master recording button");
        assert!(
            button.rect.col >= layout.rect.col
                && button.rect.row >= layout.rect.row
                && button.rect.col + button.rect.width <= layout.rect.col + layout.rect.width
                && button.rect.row + button.rect.height <= layout.rect.row + layout.rect.height,
            "master recording button should be inside the transport panel: button={:?} panel={:?}",
            button.rect,
            layout.rect
        );

        let samples_button =
            find_layout_node_by_stable_key(&layout, "transport-samples-sidebar-button")
                .expect("samples sidebar button");
        let mixer_button = find_layout_node_by_stable_key(&layout, "transport-mixer-panel-button")
            .expect("mixer panel button");
        let fx_button = find_layout_node_by_stable_key(&layout, "transport-fx-panel-button")
            .expect("FX panel button");
        let save_button =
            find_layout_node_by_stable_key(&layout, "transport-save-button").expect("save button");
        assert_finite_nonzero_rect(samples_button, "samples sidebar button");
        assert_finite_nonzero_rect(mixer_button, "mixer panel button");
        assert_finite_nonzero_rect(fx_button, "FX panel button");
        assert_finite_nonzero_rect(save_button, "save button");
        assert!(
            samples_button.rect.col + samples_button.rect.width <= mixer_button.rect.col,
            "samples sidebar button should be to the left of mixer; samples={:?} mixer={:?}",
            samples_button.rect,
            mixer_button.rect
        );
        assert!(
            mixer_button.rect.col + mixer_button.rect.width <= fx_button.rect.col,
            "mixer panel button should be to the left of FX; mixer={:?} fx={:?}",
            mixer_button.rect,
            fx_button.rect
        );
        assert!(
            fx_button.rect.col + fx_button.rect.width <= save_button.rect.col,
            "FX panel button should be to the left of save; fx={:?} save={:?}",
            fx_button.rect,
            save_button.rect
        );

        let mixer_icon = find_layout_node_by_widget_type(mixer_button, "mix-panel-icon")
            .expect("mixer panel icon");
        let callback = mixer_icon
            .props
            .get("on-click")
            .cloned()
            .expect("mixer panel button on-click");
        editor
            .runtime_mut()
            .eval_str("(set! eseq.seq-core-state/mixer-panel-visible true)")
            .expect("reset mixer panel visibility");
        editor
            .runtime_mut()
            .invoke(
                callback,
                vec![Value::Number(0.0), Value::Number(0.0), Value::Bool(false)],
            )
            .expect("invoke mixer panel button");
        editor.refresh_runtime_side_effects();
        assert_eq!(
            editor
                .runtime_mut()
                .eval_str("eseq.seq-core-state/mixer-panel-visible")
                .unwrap(),
            Some(Value::Bool(false)),
            "mixer panel button should toggle mixer-panel-visible"
        );

        let fx_icon =
            find_layout_node_by_widget_type(fx_button, "fx-panel-icon").expect("FX panel icon");
        let callback = fx_icon
            .props
            .get("on-click")
            .cloned()
            .expect("FX panel button on-click");
        editor
            .runtime_mut()
            .eval_str("(set! eseq.seq-core-state/lower-panel-visible true)")
            .expect("reset FX panel visibility");
        editor
            .runtime_mut()
            .invoke(
                callback,
                vec![Value::Number(0.0), Value::Number(0.0), Value::Bool(false)],
            )
            .expect("invoke FX panel button");
        editor.refresh_runtime_side_effects();
        assert_eq!(
            editor
                .runtime_mut()
                .eval_str("eseq.seq-core-state/lower-panel-visible")
                .unwrap(),
            Some(Value::Bool(false)),
            "FX panel button should toggle lower-panel-visible"
        );
    }

