    #[test]
    fn metal_seq_process_lanes_render_as_expanded_selector_and_knobs() {
        let mut editor = full_grid_editor_for_scroll_tests();
        install_sparse_transpose_process_lane_fixture(&mut editor);
        editor
            .runtime_mut()
            .eval_str(
                r#"
                (eseq.sequencer/set-track-expanded 0 true)
                (eseq.sequencer/set-track-param-mode 0 7)
                "#,
            )
            .expect("expand track and select process lane");
        editor.refresh_runtime_side_effects();

        let sequencer_id = editor
            .buffers
            .iter()
            .find(|buffer| buffer.name == "*sequencer*")
            .expect("sequencer buffer should exist")
            .id;
        editor.set_active_buffer(sequencer_id);
        editor.set_layout_viewport(180, 30);
        let layout = editor
            .widget_layout()
            .expect("expanded sequencer layout should build");
        assert!(
            find_layout_node_by_stable_key_suffix(&layout, "/expanded-param-tab-0-7").is_none(),
            "process lanes should not consume direct step-param tab slots"
        );
        let process_selector =
            find_layout_node_by_stable_key_suffix(&layout, "/expanded-process-lane-selector-0")
                .expect("process lane selector should render");
        assert_finite_nonzero_rect(process_selector, "process lane selector");
        assert_eq!(
            process_selector.props.get("value"),
            Some(&Value::String("1 st/amount".to_string())),
            "selected process lane should be visible in the process-lane selector"
        );
        assert!(
            value_contains_string(
                process_selector
                    .props
                    .get("options")
                    .expect("process selector options"),
                "none"
            ),
            "process selector should offer a no-process-lane option"
        );
        let summary = find_layout_node_by_stable_key_suffix(&layout, "/expanded-step-summary-0")
            .expect("process lane summary should render");
        assert!(
            summary.rect.width >= 13.0,
            "process lane summary should reserve room for the selected lane label: {:?}",
            summary.rect
        );
        assert!(
            find_layout_node_by_text(&layout, "sparse-transpose / amount").is_some(),
            "selected process lane header should render the full process/inlet label"
        );
        assert!(
            find_layout_node_by_stable_key(&layout, "seqv-process-inlet-0-0-limit").is_none(),
            "expanded process lane should not render slot-level process inlet numberpickers"
        );
        assert!(
            find_layout_node_by_stable_key(&layout, "seqv-process-port-map-0-0-__default")
                .is_none(),
            "fixed sparse-transpose target should not render a map button"
        );
        assert!(
            find_layout_node_by_stable_key(&layout, "seqv-process-lane-map-0-0-__default")
                .is_none(),
            "fixed sparse-transpose target should not render a lane map button"
        );
    }

