    #[test]
    fn metal_seq_sequencer_expanded_page_boundary_updates_stable_slots_without_rerendering_rows() {
        let mut editor = full_grid_editor_for_scroll_tests();
        set_full_grid_track_count(&mut editor, 2, 32);
        editor.runtime_mut().run_reactive_cycle();
        editor.refresh_runtime_side_effects();
        let sequencer_id = editor
            .buffers
            .iter()
            .find(|buffer| buffer.name == "*sequencer*")
            .expect("sequencer buffer should exist")
            .id;
        editor.set_active_buffer(sequencer_id);
        editor.set_layout_viewport(220, 200);
        editor
            .runtime_mut()
            .set_reactive("SEQ", "playing", Value::Bool(true));
        editor
            .runtime_mut()
            .set_reactive("SEQ", "auto-follow", Value::Bool(true));
        editor.runtime_mut().run_reactive_cycle();
        editor
            .runtime_mut()
            .eval_str("(do (eseq.sequencer/track-menu-click 0) (eseq.sequencer/track-menu-click 1))")
            .expect("expand two sequencer rows");
        editor.refresh_runtime_side_effects();
        let initial_layout = editor
            .widget_layout()
            .expect("expanded two-row sequencer layout should build");
        assert_eq!(
            find_layout_node_by_stable_key_suffix(&initial_layout, "/expanded-step-label-0-0")
                .and_then(|node| layout_prop_number(node, "value")),
            Some(1.0),
            "slot 0 should initially show absolute step 1"
        );
        assert_eq!(
            find_layout_node_by_stable_key_suffix(&initial_layout, "/expanded-step-label-0-0")
                .and_then(|node| node.props.get("h-align")),
            Some(&Value::Keyword("center".to_string())),
            "fixed-width step labels should center their text under the toggle"
        );
        let _ = editor.take_dirty_widget_ids();
        let before_revision = editor.widget_layout_revision();

        for track in 0..2 {
            set_test_expanded_step_slot_projection(&mut editor, track, track, 1, 0, 32, 16, 16);
        }
        editor.runtime_mut().run_reactive_cycle();

        let pending = editor.runtime_mut().take_pending_buffer_widget_trees();
        let sequencer_updates = pending
            .iter()
            .filter(|pending| {
                matches!(
                    pending.target(),
                    eseqlisp::vm::EffectTarget::BufferName(name) if name == "*sequencer*"
                )
            })
            .count();
        assert_eq!(
            sequencer_updates,
            0,
            "page-boundary projection should update bound slot props without rebuilding sequencer rows; got {} pending updates",
            pending.len()
        );
        assert_eq!(
            editor.widget_layout_revision(),
            before_revision,
            "page-boundary slot projection should not bump the active layout revision"
        );

        let paged_layout = editor
            .widget_layout()
            .expect("paged expanded sequencer layout should still exist");
        let slot_0_label =
            find_layout_node_by_stable_key_suffix(&paged_layout, "/expanded-step-label-0-0")
                .expect("track 0 slot 0 label after page flip");
        assert_finite_nonzero_rect(slot_0_label, "track 0 slot 0 label after page flip");
        assert_eq!(
            layout_prop_number(slot_0_label, "value"),
            Some(17.0),
            "stable slot 0 should now display absolute step 17"
        );
        let slot_0_playhead =
            find_layout_node_by_stable_key(&paged_layout, "seqv-expanded-step-playhead-probe-0-0")
                .expect("track 0 slot 0 playhead after page flip");
        assert!(
            layout_tree_has_reactive_prop_field(
                slot_0_playhead,
                "active",
                "SEQ",
                &expanded_step_slot_playhead_field(0, 0),
            ),
            "slot 0 playhead should keep the stable slot playhead binding"
        );
        assert_eq!(
            editor
                .runtime_mut()
                .eval_str(r#"(reactive-get "SEQ" "seqv-slot-playhead-active-0-0")"#)
                .unwrap(),
            Some(Value::Bool(true)),
            "stable slot 0 playhead binding should reflect absolute step 16"
        );
    }

    #[test]
    fn metal_seq_sequencer_expanded_timebase_uses_default_or_selected_step_plock_path() {
        let mut editor = full_grid_editor_for_scroll_tests();
        let sequencer_id = editor
            .buffers
            .iter()
            .find(|buffer| buffer.name == "*sequencer*")
            .expect("sequencer buffer should exist")
            .id;
        editor.set_active_buffer(sequencer_id);
        editor.set_layout_viewport(140, 20);

        let calls = Arc::new(Mutex::new(Vec::<String>::new()));
        let has_selection = Arc::new(std::sync::atomic::AtomicBool::new(false));

        {
            let calls = Arc::clone(&calls);
            editor
                .runtime_mut()
                .register_native("seq-set-track", move |args, _ctx| {
                    let track = match args.first() {
                        Some(Value::Number(track)) => track.to_string(),
                        other => format!("{other:?}"),
                    };
                    calls.lock().unwrap().push(format!("track:{track}"));
                    Ok(Value::Bool(true))
                });
        }
        editor
            .runtime_mut()
            .register_native("seq-pause-auto-follow", |_args, _ctx| Ok(Value::Bool(true)));
        {
            let has_selection = Arc::clone(&has_selection);
            editor
                .runtime_mut()
                .register_native("seq-has-selection?", move |_args, _ctx| {
                    Ok(Value::Bool(has_selection.load(Ordering::Relaxed)))
                });
        }
        {
            let calls = Arc::clone(&calls);
            editor
                .runtime_mut()
                .register_native("seq-set-timebase", move |args, _ctx| {
                    let label = match args.first() {
                        Some(Value::String(label)) => label.clone(),
                        other => format!("{other:?}"),
                    };
                    calls.lock().unwrap().push(format!("default:{label}"));
                    Ok(Value::Bool(true))
                });
        }
        {
            let calls = Arc::clone(&calls);
            editor
                .runtime_mut()
                .register_native("seq-plock-timebase", move |args, _ctx| {
                    let label = match args.first() {
                        Some(Value::String(label)) => label.clone(),
                        other => format!("{other:?}"),
                    };
                    calls.lock().unwrap().push(format!("plock:{label}"));
                    Ok(Value::Bool(true))
                });
        }

        editor
            .runtime_mut()
            .eval_str("(eseq.sequencer/track-menu-click 0)")
            .expect("expand sequencer row");
        editor.refresh_runtime_side_effects();
        calls.lock().unwrap().clear();
        let layout = editor
            .widget_layout()
            .expect("expanded sequencer layout should build");
        assert!(
            find_layout_node_by_stable_key(&layout, "seqv-timebase-0").is_none(),
            "collapsed-row timebase dropdown should stay removed"
        );
        let timebase = find_layout_node_by_stable_key_suffix(&layout, "/expanded-timebase-0")
            .expect("expanded sequencer row timebase should render");
        let callback = timebase
            .props
            .get("on-change")
            .cloned()
            .expect("expanded sequencer row timebase on-change");

        editor
            .runtime_mut()
            .invoke(callback.clone(), vec![Value::String("8".to_string())])
            .expect("invoke expanded sequencer row default timebase");
        assert_eq!(
            calls.lock().unwrap().as_slice(),
            ["track:0", "default:8"],
            "without selected steps the expanded row dropdown should update the track default"
        );

        calls.lock().unwrap().clear();
        has_selection.store(true, Ordering::Relaxed);
        editor
            .runtime_mut()
            .invoke(callback, vec![Value::String("4T".to_string())])
            .expect("invoke expanded sequencer row selected-step timebase");
        assert_eq!(
            calls.lock().unwrap().as_slice(),
            ["track:0", "plock:4T"],
            "with selected steps on the current expanded row the dropdown should p-lock timebase"
        );
    }

    #[test]
    fn metal_seq_sequencer_pattern_switch_updates_existing_step_bindings() {
        let track_count = 10;
        let mut editor = sequencer_perf_editor(track_count, 32);

        let initial_layout = editor
            .widget_layout()
            .expect("initial sequencer layout should build");
        let initial_step = find_layout_node_by_stable_key_suffix(&initial_layout, "/step-cell-0-0")
            .expect("initial step cell should render");
        assert_eq!(
            layout_prop_bool(compact_step_shell(initial_step), "active"),
            Some(true),
            "fixture generation 0 should render track 0 step 0 active"
        );

        apply_sequencer_perf_pattern(&mut editor, track_count, 48, 1);
        editor.runtime_mut().run_reactive_cycle();
        editor.refresh_runtime_side_effects();
        if let Some(status) = editor.runtime_mut().take_status_message() {
            panic!("sequencer pattern switch binding status: {status}");
        }

        let switched_layout = editor
            .widget_layout()
            .expect("switched sequencer layout should build");
        assert_eq!(
            count_stable_key_prefix(&switched_layout, "eseq.sequencer/step-cell-"),
            track_count * 48,
            "pattern switch should render the new pattern length"
        );
        let switched_step = find_layout_node_by_stable_key_suffix(&switched_layout, "/step-cell-0-0")
            .expect("existing keyed step cell should still render after switch");
        assert_eq!(
            layout_prop_bool(compact_step_shell(switched_step), "active"),
            Some(false),
            "track 0 step 0 active binding should reflect the switched pattern"
        );
    }

    #[test]
    #[ignore = "performance benchmark; run with --ignored --nocapture"]
    fn metal_seq_sequencer_shift_drag_selection_and_render_perf() {
        use crossterm::event::{KeyModifiers, MouseButton, MouseEvent, MouseEventKind};

        fn mouse_event(kind: MouseEventKind, col: f32, row: f32) -> MouseEvent {
            MouseEvent {
                kind,
                column: col as u16,
                row: row as u16,
                modifiers: KeyModifiers::SHIFT,
            }
        }

        fn percentile(sorted: &[f64], pct: f64) -> f64 {
            let index = ((sorted.len().saturating_sub(1) as f64) * pct).round() as usize;
            sorted[index.min(sorted.len().saturating_sub(1))]
        }

        fn summarize(label: &str, values: &[f64]) {
            let mut sorted = values.to_vec();
            sorted.sort_by(|a, b| a.total_cmp(b));
            println!(
                "{label:>12}: median={:7.3}ms p95={:7.3}ms min={:7.3}ms max={:7.3}ms",
                percentile(&sorted, 0.50),
                percentile(&sorted, 0.95),
                sorted.first().copied().unwrap_or(0.0),
                sorted.last().copied().unwrap_or(0.0),
            );
        }

        let track_count = 20;
        let step_count = 32;
        let drag_end_step = 7;
        let warmup_iterations = 5;
        let measured_iterations = 20;
        let selected_ranges = Arc::new(Mutex::new(Vec::<(usize, usize)>::new()));
        let mut editor = sequencer_perf_editor(track_count, step_count);
        editor
            .runtime_mut()
            .eval_str(
                r#"
                  (defstate step-drag-anchor nil)
                  (def eseq.step-grid-interactions/selection-click? (evt) (get evt :shift))
                  (def eseq.step-grid-interactions/step-pointer-down-for-track (track step evt use-selection)
                    (do (set! step-drag-anchor step) (seq-select-step-range step step)))
                  (def eseq.step-grid-interactions/step-select-drag-over-for-track (track step evt)
                    (seq-select-step-range step-drag-anchor step))
                  (def eseq.step-grid-interactions/step-pointer-up (step evt) (set! step-drag-anchor nil))
                "#,
            )
            .expect("install standalone selection gesture support");
        editor
            .runtime_mut()
            .register_native("seq-pause-auto-follow", |_args, _ctx| Ok(Value::Bool(true)));
        editor
            .runtime_mut()
            .register_native("seq-set-track", |_args, _ctx| Ok(Value::Bool(true)));
        editor
            .runtime_mut()
            .register_native("seq-track-step-active?", |_args, _ctx| {
                Ok(Value::Bool(true))
            });
        {
            let selected_ranges = Arc::clone(&selected_ranges);
            editor
                .runtime_mut()
                .register_native("seq-select-step-range", move |args, _ctx| {
                    let number = |value: Option<&Value>| match value {
                        Some(Value::Number(value)) => *value as usize,
                        _ => usize::MAX,
                    };
                    let start = number(args.first());
                    let end = number(args.get(1));
                    selected_ranges.lock().unwrap().push((start, end));
                    Ok(Value::Nil)
                });
        }

        let initial_frame =
            eseqlisp::frame::build_tiled_render_frame_borderless(&mut editor, 150, 44);
        let tile = initial_frame
            .tiles
            .iter()
            .find(|tile| tile.frame.buffer_name == "*sequencer*")
            .expect("sequencer selection perf tile should render");
        let layout = tile
            .frame
            .widget_layout
            .as_deref()
            .expect("sequencer selection perf layout should build");
        let start = find_layout_node_by_stable_key_suffix(layout, "/step-cell-0-0")
            .expect("selection start step");
        let end =
            find_layout_node_by_stable_key_suffix(layout, &format!("/step-cell-0-{drag_end_step}"))
                .expect("selection end step");
        let down_callback = start
            .props
            .get("on-mouse-down")
            .cloned()
            .expect("selection start callback");
        let up_callback = end
            .props
            .get("on-mouse-up")
            .cloned()
            .expect("selection end callback");
        let selection_event = map_value([("shift", Value::Bool(true))]);
        let start_point = (
            tile.body_rect.col + start.rect.col + start.rect.width * 0.5,
            tile.body_rect.row + start.rect.row + start.rect.height * 0.5,
        );
        let end_point = (
            tile.body_rect.col + end.rect.col + end.rect.width * 0.5,
            tile.body_rect.row + end.rect.row + end.rect.height * 0.5,
        );

        let mut input_samples = Vec::with_capacity(measured_iterations);
        let mut frame_samples = Vec::with_capacity(measured_iterations);
        let mut total_samples = Vec::with_capacity(measured_iterations);
        for iteration in 0..(warmup_iterations + measured_iterations) {
            selected_ranges.lock().unwrap().clear();
            let total_start = std::time::Instant::now();
            let input_start = std::time::Instant::now();
            editor
                .runtime_mut()
                .invoke(down_callback.clone(), vec![selection_event.clone()])
                .expect("start selection gesture");
            editor.handle_tiled_mouse_precise(
                mouse_event(
                    MouseEventKind::Drag(MouseButton::Left),
                    start_point.0,
                    start_point.1,
                ),
                start_point.0,
                start_point.1,
                0,
            );
            editor.handle_tiled_mouse_precise(
                mouse_event(
                    MouseEventKind::Drag(MouseButton::Left),
                    end_point.0,
                    end_point.1,
                ),
                end_point.0,
                end_point.1,
                0,
            );
            editor
                .runtime_mut()
                .invoke(up_callback.clone(), vec![selection_event.clone()])
                .expect("finish selection gesture");
            let input_ms = input_start.elapsed().as_secs_f64() * 1000.0;

            let frame_start = std::time::Instant::now();
            let frame = eseqlisp::frame::build_tiled_render_frame_borderless(&mut editor, 150, 44);
            let frame_ms = frame_start.elapsed().as_secs_f64() * 1000.0;
            assert_eq!(
                frame.tiles.len(),
                1,
                "selection frame should render one tile"
            );
            let observed_ranges = selected_ranges.lock().unwrap().clone();
            assert!(
                observed_ranges
                    .iter()
                    .any(|range| *range == (0, drag_end_step)),
                "shift drag should select through the target step; start={start_point:?} end={end_point:?} observed={observed_ranges:?}"
            );

            if iteration >= warmup_iterations {
                input_samples.push(input_ms);
                frame_samples.push(frame_ms);
                total_samples.push(total_start.elapsed().as_secs_f64() * 1000.0);
            }
        }

        println!(
            "sequencer shift-drag selection perf: {track_count} tracks, {step_count} steps, selecting 0..={drag_end_step}, {measured_iterations} measured iterations after {warmup_iterations} warmups"
        );
        summarize("input", &input_samples);
        summarize("frame", &frame_samples);
        summarize("total", &total_samples);
    }

    #[test]
    fn metal_seq_mixer_v2_pattern_cell_state_updates_existing_bindings() {
        let track_count = 10;
        let cell_count = 8;
        let mut editor = mixer_v2_perf_editor(track_count, cell_count);

        let initial_layout = editor
            .widget_layout()
            .expect("initial mixer layout should build");
        let mut pattern_widget_ids = std::collections::HashSet::new();
        for track in 0..track_count {
            for cell in 0..cell_count {
                let pattern_id = track * 100 + cell + 1;
                let key = format!("eseq.mixer/track-pattern-cell-{track}-{pattern_id}");
                pattern_widget_ids.insert(
                    find_layout_node_by_stable_key(&initial_layout, &key)
                        .unwrap_or_else(|| panic!("missing mixer pattern cell {key}"))
                        .widget_id,
                );
            }
        }
        let initial_cell =
            find_layout_node_by_stable_key_suffix(&initial_layout, "/track-pattern-cell-0-1")
                .expect("initial active pattern cell");
        assert_eq!(
            layout_prop_bool(initial_cell, "active"),
            Some(true),
            "fixture generation 0 should render track 0 pattern 1 active"
        );
        let initial_glyph = find_layout_node_by_widget_type(initial_cell, "sound-glyph")
            .expect("active mixer pattern cell should contain its sound glyph");
        assert_finite_nonzero_rect(initial_glyph, "active mixer pattern sound glyph");
        assert_layout_inside(initial_glyph, initial_cell, "active mixer pattern sound glyph");
        assert_eq!(
            layout_prop_number(initial_glyph, "play-glyph-padding"),
            Some(0.14)
        );
        assert_eq!(
            layout_prop_number(initial_glyph, "play-glyph-opacity"),
            Some(0.4)
        );
        assert_eq!(
            initial_glyph.props.get("play-color"),
            Some(&Value::Keyword("white".to_string()))
        );

        let _ = editor.take_dirty_widget_ids();
        apply_mixer_v2_perf_pattern(&mut editor, track_count, cell_count, 1);
        let dirty_widgets = editor.take_dirty_widget_ids();
        assert!(
            !dirty_widgets.is_empty(),
            "pattern-cell binding updates should dirty concrete widgets"
        );
        assert!(
            dirty_widgets
                .iter()
                .all(|widget_id| pattern_widget_ids.contains(widget_id)),
            "pattern-cell binding updates should dirty only pattern-cell widgets: {dirty_widgets:?}"
        );

        editor.runtime_mut().run_reactive_cycle();
        editor.refresh_runtime_side_effects();
        if let Some(trace) = editor.runtime().last_ui_invalidation_trace() {
            assert!(
                !trace
                    .affected_buffers
                    .iter()
                    .any(|buffer| buffer == "*mixer*"),
                "pattern-cell binding updates should not rerun the mixer tree: {trace:?}"
            );
        }

        let switched_layout = editor
            .widget_layout()
            .expect("switched mixer layout should still build");
        let switched_old_cell =
            find_layout_node_by_stable_key_suffix(&switched_layout, "/track-pattern-cell-0-1")
                .expect("old active pattern cell");
        let switched_new_cell =
            find_layout_node_by_stable_key_suffix(&switched_layout, "/track-pattern-cell-0-2")
                .expect("new active pattern cell");
        assert_eq!(
            layout_prop_bool(switched_old_cell, "active"),
            Some(false),
            "track 0 pattern 1 active binding should reflect the switched pattern"
        );
        assert_eq!(
            layout_prop_bool(switched_new_cell, "active"),
            Some(true),
            "track 0 pattern 2 active binding should reflect the switched pattern"
        );
    }

    #[test]
    fn metal_seq_toggle_mixer_panel_restores_retained_10_track_layouts() {
        #[derive(Clone, Copy)]
        struct CachedLayoutState {
            ptr: usize,
            viewport_width: f32,
            viewport_height: f32,
            root_width: f32,
        }

        fn cached_layout_state(editor: &eseqlisp::Editor, buffer_name: &str) -> CachedLayoutState {
            let buffer_idx = editor
                .buffers
                .iter()
                .position(|buffer| buffer.name == buffer_name)
                .unwrap_or_else(|| panic!("missing buffer {buffer_name}"));
            let leaf = editor
                .tile_root
                .find_leaf_by_buffer_idx(buffer_idx)
                .unwrap_or_else(|| panic!("missing tile for buffer {buffer_name}"));
            let layout = leaf
                .cached_layout
                .as_ref()
                .unwrap_or_else(|| panic!("missing cached layout for {buffer_name}"));
            CachedLayoutState {
                ptr: std::sync::Arc::as_ptr(layout) as usize,
                viewport_width: leaf.widget_viewport_width,
                viewport_height: leaf.widget_viewport_height,
                root_width: layout.rect.width,
            }
        }

        fn same_viewport(a: CachedLayoutState, b: CachedLayoutState) -> bool {
            (a.viewport_width - b.viewport_width).abs() <= 0.05
                && (a.viewport_height - b.viewport_height).abs() <= 0.05
        }

        fn assert_reused_or_relaid_out_for_viewport_change(
            buffer_name: &str,
            initial: CachedLayoutState,
            shown: CachedLayoutState,
        ) {
            if same_viewport(initial, shown) {
                assert_eq!(
                    shown.ptr, initial.ptr,
                    "{buffer_name} show should restore the retained layout when its viewport is unchanged"
                );
            } else {
                assert_ne!(
                    shown.ptr, initial.ptr,
                    "{buffer_name} layout must not be reused after the tile viewport changes"
                );
                assert!(
                    (shown.root_width - shown.viewport_width).abs() <= 0.05,
                    "{buffer_name} layout should be rebuilt for the changed viewport width: root={} viewport={}",
                    shown.root_width,
                    shown.viewport_width
                );
            }
        }

        let track_count = 10;
        let mut editor = full_grid_editor_for_scroll_tests();
        set_full_grid_track_count(&mut editor, track_count, 16);
        editor.runtime_mut().run_reactive_cycle();
        editor.refresh_runtime_side_effects();
        editor.refresh_visible_layouts_for_buffer_named("*mixer*");
        let frame = eseqlisp::frame::build_tiled_render_frame_borderless(&mut editor, 180, 90);
        let mixer_layout = frame
            .tiles
            .iter()
            .find(|tile| tile.frame.buffer_name == "*mixer*")
            .and_then(|tile| tile.frame.widget_layout.as_ref())
            .expect("initial mixer layout should render");
        assert_eq!(
            count_stable_key_prefix(mixer_layout, "eseq.mixer/track-pattern-cell-"),
            track_count,
            "10-track fixture should render one mixer pattern cell per track"
        );

        let initial_mixer = cached_layout_state(&editor, "*mixer*");
        let initial_sequencer = cached_layout_state(&editor, "*sequencer*");
        let initial_step = cached_layout_state(&editor, "*step*");
        let initial_track = cached_layout_state(&editor, "*track*");

        editor
            .runtime_mut()
            .eval_str("(eseq.seq-panels/seq-toggle-mixer-panel)")
            .expect("hide mixer panel");
        editor.refresh_runtime_side_effects();
        let hidden_frame =
            eseqlisp::frame::build_tiled_render_frame_borderless(&mut editor, 180, 90);
        assert!(
            hidden_frame
                .tiles
                .iter()
                .all(|tile| tile.frame.buffer_name != "*mixer*"),
            "hide toggle should remove the mixer tile"
        );

        editor
            .runtime_mut()
            .eval_str("(eseq.seq-panels/seq-toggle-mixer-panel)")
            .expect("show mixer panel");
        editor.refresh_runtime_side_effects();
        editor.refresh_visible_layouts_for_buffer_named("*mixer*");
        let shown_frame =
            eseqlisp::frame::build_tiled_render_frame_borderless(&mut editor, 180, 90);
        assert!(
            shown_frame
                .tiles
                .iter()
                .any(|tile| tile.frame.buffer_name == "*mixer*"),
            "show toggle should restore the mixer tile"
        );

        let shown_mixer = cached_layout_state(&editor, "*mixer*");
        assert_reused_or_relaid_out_for_viewport_change("*mixer*", initial_mixer, shown_mixer);
        let shown_sequencer = cached_layout_state(&editor, "*sequencer*");
        assert_reused_or_relaid_out_for_viewport_change(
            "*sequencer*",
            initial_sequencer,
            shown_sequencer,
        );
        assert_reused_or_relaid_out_for_viewport_change(
            "*step*",
            initial_step,
            cached_layout_state(&editor, "*step*"),
        );
        assert_reused_or_relaid_out_for_viewport_change(
            "*track*",
            initial_track,
            cached_layout_state(&editor, "*track*"),
        );
    }

    #[test]
    #[ignore = "performance benchmark; run with --ignored --nocapture"]
    fn metal_seq_toggle_mixer_panel_show_perf_10_tracks() {
        #[derive(Clone, Copy)]
        struct Sample {
            hide_ms: f64,
            show_eval_ms: f64,
            show_side_effects_ms: f64,
            show_frame_ms: f64,
            show_total_ms: f64,
        }

        fn percentile(sorted: &[f64], pct: f64) -> f64 {
            let index = ((sorted.len().saturating_sub(1) as f64) * pct).round() as usize;
            sorted[index.min(sorted.len().saturating_sub(1))]
        }

        fn summarize(label: &str, values: &[f64]) {
            let mut sorted = values.to_vec();
            sorted.sort_by(|a, b| a.total_cmp(b));
            let min = sorted.first().copied().unwrap_or(0.0);
            let median = percentile(&sorted, 0.50);
            let p95 = percentile(&sorted, 0.95);
            let max = sorted.last().copied().unwrap_or(0.0);
            println!(
                "{label:>18}: min={min:7.3}ms median={median:7.3}ms p95={p95:7.3}ms max={max:7.3}ms"
            );
        }

        let track_count = 10;
        let step_count = 16;
        let warmup_iterations = 3;
        let measured_iterations = 10;
        let mut editor = full_grid_editor_for_scroll_tests();
        set_full_grid_track_count(&mut editor, track_count, step_count);
        editor.runtime_mut().run_reactive_cycle();
        editor.refresh_runtime_side_effects();
        editor.refresh_visible_layouts_for_buffer_named("*mixer*");
        let frame = eseqlisp::frame::build_tiled_render_frame_borderless(&mut editor, 180, 90);
        let mixer_layout = frame
            .tiles
            .iter()
            .find(|tile| tile.frame.buffer_name == "*mixer*")
            .and_then(|tile| tile.frame.widget_layout.as_ref())
            .expect("initial full grid should render mixer layout");
        assert_eq!(
            count_stable_key_prefix(mixer_layout, "eseq.mixer/track-pattern-cell-"),
            track_count,
            "10-track fixture should render one mixer pattern cell per track"
        );

        let mut samples = Vec::with_capacity(measured_iterations);
        for iteration in 0..(warmup_iterations + measured_iterations) {
            let hide_start = std::time::Instant::now();
            editor
                .runtime_mut()
                .eval_str("(eseq.seq-panels/seq-toggle-mixer-panel)")
                .expect("hide mixer panel");
            editor.refresh_runtime_side_effects();
            let hidden_frame =
                eseqlisp::frame::build_tiled_render_frame_borderless(&mut editor, 180, 90);
            assert!(
                hidden_frame
                    .tiles
                    .iter()
                    .all(|tile| tile.frame.buffer_name != "*mixer*"),
                "hide toggle should remove the mixer tile"
            );
            let hide_ms = hide_start.elapsed().as_secs_f64() * 1000.0;

            let show_total_start = std::time::Instant::now();
            let show_eval_start = std::time::Instant::now();
            editor
                .runtime_mut()
                .eval_str("(eseq.seq-panels/seq-toggle-mixer-panel)")
                .expect("show mixer panel");
            let show_eval_ms = show_eval_start.elapsed().as_secs_f64() * 1000.0;

            let show_side_effects_start = std::time::Instant::now();
            editor.refresh_runtime_side_effects();
            editor.refresh_visible_layouts_for_buffer_named("*mixer*");
            let show_side_effects_ms = show_side_effects_start.elapsed().as_secs_f64() * 1000.0;

            let show_frame_start = std::time::Instant::now();
            let shown_frame =
                eseqlisp::frame::build_tiled_render_frame_borderless(&mut editor, 180, 90);
            let show_frame_ms = show_frame_start.elapsed().as_secs_f64() * 1000.0;
            let shown_mixer_layout = shown_frame
                .tiles
                .iter()
                .find(|tile| tile.frame.buffer_name == "*mixer*")
                .and_then(|tile| tile.frame.widget_layout.as_ref())
                .expect("show toggle should render mixer layout");
            assert_eq!(
                count_stable_key_prefix(shown_mixer_layout, "eseq.mixer/track-pattern-cell-"),
                track_count,
                "show toggle should keep every mixer track rendered"
            );

            let show_total_ms = show_total_start.elapsed().as_secs_f64() * 1000.0;
            if iteration >= warmup_iterations {
                samples.push(Sample {
                    hide_ms,
                    show_eval_ms,
                    show_side_effects_ms,
                    show_frame_ms,
                    show_total_ms,
                });
            }
        }

        println!(
            "seq-toggle-mixer-panel show perf: {track_count} tracks, {} measured iterations after {} warmups",
            measured_iterations, warmup_iterations
        );
        summarize(
            "hide-total",
            &samples
                .iter()
                .map(|sample| sample.hide_ms)
                .collect::<Vec<_>>(),
        );
        summarize(
            "show-eval",
            &samples
                .iter()
                .map(|sample| sample.show_eval_ms)
                .collect::<Vec<_>>(),
        );
        summarize(
            "show-side-effects",
            &samples
                .iter()
                .map(|sample| sample.show_side_effects_ms)
                .collect::<Vec<_>>(),
        );
        summarize(
            "show-frame",
            &samples
                .iter()
                .map(|sample| sample.show_frame_ms)
                .collect::<Vec<_>>(),
        );
        summarize(
            "show-total",
            &samples
                .iter()
                .map(|sample| sample.show_total_ms)
                .collect::<Vec<_>>(),
        );
    }

    #[test]
    #[ignore = "performance benchmark; run with --ignored --nocapture"]
    fn metal_seq_sequencer_pattern_switch_perf_10_tracks_variable_lengths() {
        #[derive(Clone, Copy)]
        struct Sample {
            update_ms: f64,
            reactive_ms: f64,
            side_effects_ms: f64,
            frame_ms: f64,
            total_ms: f64,
        }

        fn percentile(sorted: &[f64], pct: f64) -> f64 {
            let index = ((sorted.len().saturating_sub(1) as f64) * pct).round() as usize;
            sorted[index.min(sorted.len().saturating_sub(1))]
        }

        fn summarize(label: &str, values: &[f64]) {
            let mut sorted = values.to_vec();
            sorted.sort_by(|a, b| a.total_cmp(b));
            let min = sorted.first().copied().unwrap_or(0.0);
            let median = percentile(&sorted, 0.50);
            let p95 = percentile(&sorted, 0.95);
            let max = sorted.last().copied().unwrap_or(0.0);
            println!(
                "{label:>12}: min={min:7.3}ms median={median:7.3}ms p95={p95:7.3}ms max={max:7.3}ms"
            );
        }

        let track_count = 10;
        let short_pattern_steps = 32;
        let long_pattern_steps = 48;
        let warmup_iterations = 3;
        let measured_iterations = 10;
        let mut editor = sequencer_perf_editor(track_count, short_pattern_steps);

        let mut samples = Vec::with_capacity(measured_iterations);
        for generation in 1..=(warmup_iterations + measured_iterations) {
            let step_count = if generation % 2 == 0 {
                short_pattern_steps
            } else {
                long_pattern_steps
            };
            let total_start = std::time::Instant::now();

            let update_start = std::time::Instant::now();
            apply_sequencer_perf_pattern(&mut editor, track_count, step_count, generation);
            let update_ms = update_start.elapsed().as_secs_f64() * 1000.0;

            let reactive_start = std::time::Instant::now();
            editor.runtime_mut().run_reactive_cycle();
            let reactive_ms = reactive_start.elapsed().as_secs_f64() * 1000.0;

            let side_effects_start = std::time::Instant::now();
            editor.refresh_runtime_side_effects();
            let side_effects_ms = side_effects_start.elapsed().as_secs_f64() * 1000.0;
            if let Some(status) = editor.runtime_mut().take_status_message() {
                panic!("sequencer pattern switch perf status: {status}");
            }

            let frame_start = std::time::Instant::now();
            let frame = eseqlisp::frame::build_render_frame(&mut editor, 150, 44);
            let frame_ms = frame_start.elapsed().as_secs_f64() * 1000.0;
            let layout = frame
                .widget_layout
                .as_ref()
                .expect("sequencer pattern switch layout should build");
            assert_eq!(
                count_stable_key_prefix(layout, "eseq.sequencer/step-cell-"),
                track_count * step_count,
                "pattern switch should keep every sequencer cell rendered"
            );

            let total_ms = total_start.elapsed().as_secs_f64() * 1000.0;
            if generation > warmup_iterations {
                samples.push(Sample {
                    update_ms,
                    reactive_ms,
                    side_effects_ms,
                    frame_ms,
                    total_ms,
                });
            }
        }

        println!(
            "sequencer pattern switch perf: {track_count} tracks, alternating {short_pattern_steps}/{long_pattern_steps} steps, {} measured iterations after {} warmups",
            measured_iterations, warmup_iterations
        );
        summarize(
            "update",
            &samples
                .iter()
                .map(|sample| sample.update_ms)
                .collect::<Vec<_>>(),
        );
        summarize(
            "reactive",
            &samples
                .iter()
                .map(|sample| sample.reactive_ms)
                .collect::<Vec<_>>(),
        );
        summarize(
            "side-effects",
            &samples
                .iter()
                .map(|sample| sample.side_effects_ms)
                .collect::<Vec<_>>(),
        );
        summarize(
            "frame",
            &samples
                .iter()
                .map(|sample| sample.frame_ms)
                .collect::<Vec<_>>(),
        );
        summarize(
            "total",
            &samples
                .iter()
                .map(|sample| sample.total_ms)
                .collect::<Vec<_>>(),
        );
    }

